import pandas as pd

# Create the sample dataset
data = {
    'id': [1, 2, 3, 4, 5],
    'url': ['A.com', 'A.com', 'B.com', 'B.com', 'C.com'],
    'keep_if_dup': ['Yes', 'Yes', 'No', 'No', 'No']
}

df = pd.DataFrame(data)

# Define a function to determine if a row should be kept based on the logic:
# 1. If 'keep_if_dup' is 'Yes', always keep the row (even if duplicate URL).
# 2. If 'keep_if_dup' is 'No', keep only the first occurrence of the URL.
def should_keep(row, seen_urls):
    if row['keep_if_dup'] == 'Yes':
        return True
    else:
        # For 'No', check if we have seen this URL before
        if row['url'] in seen_urls:
            return False
        else:
            seen_urls.add(row['url'])
            return True

# Apply the logic iteratively to build the result
result_rows = []
seen_urls = set()

for _, row in df.iterrows():
    if should_keep(row, seen_urls):
        result_rows.append(row)

# Create the final dataframe from the filtered rows
df_result = pd.DataFrame(result_rows)

print(df_result)

