import pandas as pd
import numpy as np

# Sample data creation based on your description
data = {
    'Col1': ['C', 'A', 'B', 'D'],
    'Col2': [33, 2.5, 42, 666],
    'Col3': [11, 4.5, 14, 1919810],
    'Col4': [['Apple', 'Orange', 'Banana'], ['Apple', 'Grape'], ['Banana'], ['Suica', 'Orange']]
}

df = pd.DataFrame(data)

# Get all unique elements from the list column (last column)
all_unique_elements = set()
for item in df.iloc[:, -1]:
    if isinstance(item, list):
        all_unique_elements.update(item)

# Create a dictionary mapping each unique element to a new column name
unique_elements = sorted(list(all_unique_elements))
element_to_col = {elem: f"{elem}" for elem in unique_elements}

# Initialize the dataframe with original columns plus new binary columns
df_expanded = df.copy()
for elem in unique_elements:
    df_expanded[elem] = 0

# Iterate through rows and set values to 1 if the element exists in the list
for idx, row in df.iterrows():
    item_list = row.iloc[-1]
    if isinstance(item_list, list):
        for elem in unique_elements:
            if elem in item_list:
                df_expanded.loc[idx, elem] = 1

# Display the result
print(df_expanded)

