import pandas as pd
import numpy as np
import yaml
import copy


def generate_test_case(test_case_id):
    def generate_ans(data):
        df = data
        df.message = df.message.replace(["\[", "\]"], ["{", "}"], regex=True).apply(
            yaml.safe_load
        )
        df1 = pd.DataFrame(df.pop("message").values.tolist(), index=df.index)
