def parse_date(date_str):
    parts = date_str.split('-')
    year = int(parts[0])
    month = int(parts[1])
    day = int(parts[2])
    return (year, month, day)

def days_in_month(year, month):
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    elif month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        else:
            return 28

def date_to_days(year, month, day):
    total_days = 0
    for y in range(1, year):
        if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):
            total_days += 366
        else:
            total_days += 365

    for m in range(1, month):
        total_days += days_in_month(year, m)

    total_days += day
    return total_days

def days_to_date(total_days):
    year = 1
    while True:
        days_in_year = 366 if ((year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)) else 365
        if total_days <= days_in_year:
            break
        total_days -= days_in_year
        year += 1

    month = 1
    while True:
        dim = days_in_month(year, month)
        if total_days <= dim:
            break
        total_days -= dim
        month += 1

    day = total_days
    return (year, month, day)

def format_date(year, month, day):
    return "{:04d}-{:02d}-{:02d}".format(year, month, day)

# Input data simulation
data_rows = [
    {'user': 'a', 'dt': '2016-01-01', 'val': 1},
    {'user': 'a', 'dt': '2016-01-02', 'val': 33},
    {'user': 'b', 'dt': '2016-01-05', 'val': 2},
    {'user': 'b', 'dt': '2016-01-06', 'val': 1}
]

# Extract unique users manually
unique_users = []
for row in data_rows:
    user = row['user']
    is_new = True
    for existing_user in unique_users:
        if existing_user == user:
            is_new = False
            break
    if is_new:
        unique_users.append(user)

# Find global min and max date across all rows
min_date_tuple = None
max_date_tuple = None

for row in data_rows:
    dt_str = row['dt']
    y, m, d = parse_date(dt_str)
    current_days = date_to_days(y, m, d)

    if min_date_tuple is None:
        min_date_tuple = (y, m, d)
        max_date_tuple = (y, m, d)
    else:
        min_days = date_to_days(min_date_tuple[0], min_date_tuple[1], min_date_tuple[2])
        max_days = date_to_days(max_date_tuple[0], max_date_tuple[1], max_date_tuple[2])

        if current_days < min_days:
            min_date_tuple = (y, m, d)
        if current_days > max_days:
            max_date_tuple = (y, m, d)

# Create a mapping of (user, date_str) -> val for quick lookup
val_map = {}
for row in data_rows:
    key = (row['user'], row['dt'])
    val_map[key] = row['val']

# Generate the full range of dates from min to max
min_days = date_to_days(min_date_tuple[0], min_date_tuple[1], min_date_tuple[2])
max_days = date_to_days(max_date_tuple[0], max_date_tuple[1], max_date_tuple[2])

all_dates = []
current_days = min_days
while current_days <= max_days:
    y, m, d = days_to_date(current_days)
    all_dates.append(format_date(y, m, d))
    current_days += 1

# Construct the final result list
result_rows = []
for user in unique_users:
    for date_str in all_dates:
        key = (user, date_str)
        if key in val_map:
            val = val_map[key]
        else:
            val = 0
        result_rows.append({'dt': date_str, 'user': user, 'val': val})

# Print the result to verify
print("dt\tuser\tval")
for row in result_rows:
    print("{}\t{}\t{}".format(row['dt'], row['user'], row['val']))

