def parse_date(date_str):
    parts = date_str.split('-')
    year = int(parts[0])
    month = int(parts[1])
    day = int(parts[2])
    return (year, month, day)

def format_date(year, month, day):
    return "{:04d}-{:02d}-{:02d}".format(year, month, day)

def add_days_to_date(year, month, day, days_to_add):
    # Simple implementation assuming no leap years for simplicity in this context
    # and handling month rollovers manually.
    # Days in months (non-leap year)
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    day += days_to_add

    while day > days_in_months[month - 1]:
        day -= days_in_months[month - 1]
        month += 1
        if month > 12:
            month = 1
            year += 1

    return (year, month, day)

def compare_dates(d1, d2):
    # Returns negative if d1 < d2, positive if d1 > d2, 0 if equal
    if d1[0] != d2[0]:
        return d1[0] - d2[0]
    if d1[1] != d2[1]:
        return d1[1] - d2[1]
    return d1[2] - d2[2]

def get_min_date(date_list):
    if not date_list:
        return None
    min_d = date_list[0]
    for i in range(1, len(date_list)):
        if compare_dates(date_list[i], min_d) < 0:
            min_d = date_list[i]
    return min_d

def get_max_date(date_list):
    if not date_list:
        return None
    max_d = date_list[0]
    for i in range(1, len(date_list)):
        if compare_dates(date_list[i], max_d) > 0:
            max_d = date_list[i]
    return max_d

def days_between(d1, d2):
    # Calculate difference in days between two dates (d2 - d1)
    # Assuming d2 >= d1 for this logic
    y1, m1, day1 = d1
    y2, m2, day2 = d2

    # Convert to absolute days from a reference point (e.g., year 0)
    # This is a simplified calculation ignoring leap years for consistency with add_days_to_date
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    total_days_1 = y1 * 365 + sum(days_in_months[:m1-1]) + day1
    total_days_2 = y2 * 365 + sum(days_in_months[:m2-1]) + day2

    return total_days_2 - total_days_1

# Input data simulation (since we cannot use pandas)
data_users = ['a', 'a', 'b', 'b']
data_dts = ['2016-01-01', '2016-01-02', '2016-01-05', '2016-01-06']
data_vals = [1, 33, 2, 1]

# Step 1: Parse dates and find global min/max
parsed_dates = []
for i in range(len(data_dts)):
    parsed_dates.append(parse_date(data_dts[i]))

global_min = get_min_date(parsed_dates)
global_max = get_max_date(parsed_dates)

# Step 2: Group data by user manually
user_groups = {}
for i in range(len(data_users)):
    u = data_users[i]
    if u not in user_groups:
        user_groups[u] = []
    user_groups[u].append({
        'dt': parsed_dates[i],
        'val': data_vals[i]
    })

# Step 3: Generate the expanded output
output_rows = []

# Sort users to ensure deterministic order (a, b)
sorted_users = []
for u in user_groups:
    sorted_users.append(u)

# Manual sort for users
for i in range(len(sorted_users)):
    for j in range(i + 1, len(sorted_users)):
        if sorted_users[i] > sorted_users[j]:
            temp = sorted_users[i]
            sorted_users[i] = sorted_users[j]
            sorted_users[j] = temp

for user in sorted_users:
    # Create a lookup for existing values for this user
    user_vals_map = {}
    for entry in user_groups[user]:
        dt_str = format_date(entry['dt'][0], entry['dt'][1], entry['dt'][2])
        user_vals_map[dt_str] = entry['val']

    # Iterate from global_min to global_max
    current_date = list(global_min) # Copy

    while True:
        dt_str = format_date(current_date[0], current_date[1], current_date[2])

        if dt_str in user_vals_map:
            val = user_vals_map[dt_str]
        else:
            val = 233

        output_rows.append({
            'user': user,
            'dt': dt_str,
            'val': val
        })

        # Check if we reached the max date
        if compare_dates(current_date, global_max) == 0:
            break

        # Increment date by 1 day
        current_date = add_days_to_date(current_date[0], current_date[1], current_date[2], 1)

# Print the result in the requested format
print("dt user val")
for i, row in enumerate(output_rows):
    print("{} {} {} {}".format(i, row['dt'], row['user'], row['val']))

