# This demonstrates how the function works on raw data structures
if __name__ == "__main__":
    # Simulating a DataFrame as a list of dictionaries
    sample_data = [
        {"Title": "Good &AMP; bad", "Description": "Less &LT; than more"},
        {"Title": "Big &GT; Small", "Description": "No entities here"},
