import re

def validate_single_space_name(name):
    """
    Returns the name if it contains exactly one space, otherwise returns None.
    Implemented without using list comprehensions or built-in aggregation functions.
    """
    if not isinstance(name, str):
        return None

    count = 0
    for char in name:
        if char == ' ':
            count += 1

    if count == 1:
        return name
    else:
        return None

def split_name_logic(name):
    """
    Splits a name into first and last parts if exactly one space exists.
    Otherwise, returns the full name as the first part and an empty string for the second.
    """
    if not isinstance(name, str):
        return [name, ""]

    count = 0
    split_index = -1

    # Find the index of the single space
    for i in range(len(name)):
        if name[i] == ' ':
            count += 1
            split_index = i

    if count == 1:
        first_part = ""
        last_part = ""

        # Extract first part manually
        for i in range(split_index):
            first_part += name[i]

        # Extract last part manually
        for i in range(split_index + 1, len(name)):
            last_part += name[i]

        return [first_part, last_part]
    else:
        return [name, ""]

