        for i in range(self.n_rows):
            k = key_values[i]
            if k not in groups:
                groups[k] = []
            groups[k].append(i)

        return GroupByIterator(groups, key_index)

class GroupByIterator:
    def __init__(self, groups_dict, key_index):
        self.groups_dict = groups_dict
        self.key_index = key_index
        self.current_group = None
        self.current_idx_in_group = 0
        self.running_sum = 0
        self.total_rows = sum(len(v) for v in groups_dict.values())

    def __iter__(self):
        return self

    def __next__(self):
        if self.current_group is None:
            # Find the first group that hasn't been processed yet
            # We need to iterate through all groups in order of appearance
            # But since we are iterating rows, we just need to find the next row's group
            pass

        # This approach is tricky because we need to maintain state across iterations
        # Let's restart with a simpler state machine approach

        raise StopIteration

def calculate_cumsum_manual(df_data, df_keys):
    n_rows = len(df_data)

    # Extract columns manually
    id_col = []
    val_col = []
    stuff_col = []

    for i in range(n_rows):
        row = df_data[i]
        id_col.append(row[df_keys.index('id')])
        val_col.append(row[df_keys.index('val')])
        stuff_col.append(row[df_keys.index('stuff')])

    # Create a list of rows with their original index
    rows_with_idx = []
    for i in range(n_rows):
        rows_with_idx.append({
            'original_idx': i,
            'id': id_col[i],
            'val': val_col[i],
            'stuff': stuff_col[i]
        })

    # Group indices by id
    groups = {}
    for row in rows_with_idx:
        rid = row['id']
        if rid not in groups:
            groups[rid] = []
        groups[rid].append(row['original_idx'])

    # Sort groups by their first appearance to maintain order
    sorted_group_ids = []
    for i in range(n_rows):
        rid = rows_with_idx[i]['id']
        if rid not in sorted_group_ids:
            sorted_group_ids.append(rid)

    # Calculate cumulative sum for each group
    result_data = []
    running_sums = {}

    for row in rows_with_idx:
        rid = row['id']
        val = row['val']

        if rid not in running_sums:
            running_sums[rid] = 0

        running_sums[rid] += val
        row['cumsum'] = running_sums[rid]
        result_data.append(row)

    # Reconstruct the dataframe structure
    new_keys = ['id', 'stuff', 'val', 'cumsum']
    new_data = []

    for row in result_data:
        new_row = {}
        for key in new_keys:
            if key == 'id':
                new_row[key] = row['id']
            elif key == 'stuff':
                new_row[key] = row['stuff']
            elif key == 'val':
                new_row[key] = row['val']
            elif key == 'cumsum':
                new_row[key] = row['cumsum']
        new_data.append(new_row)

    return DataFrame(new_data, new_keys)

# Original data
original_dict = {
    'id': ['A', 'B', 'A', 'C', 'D', 'B', 'C'], 
    'val': [1, 2, -3, 1, 5, 6, -2], 
    'stuff': ['12', '23232', '13', '1234', '3235', '3236', '732323']
}

# Create dataframe manually
df = DataFrame(original_dict, list(original_dict.keys()))

# Calculate cumulative sum
result_df = calculate_cumsum_manual(df.data, df.keys)

# Print result
