def get_unique_count(values):
    unique_list = []
    for val in values:
        is_new = True
        for u in unique_list:
            if u == val:
                is_new = False
                break
        if is_new:
            unique_list.append(val)
    return len(unique_list)

def get_relationship_type(col_a, col_b):
    # Count unique values in each column
    unique_a = get_unique_count(col_a)
    unique_b = get_unique_count(col_b)

    # Check mapping from A to B (is it one-to-one or one-to-many?)
    # For every value in A, how many distinct values in B does it map to?
    a_to_b_is_one = True
    for val_a in col_a:
        count_b_for_a = 0
        seen_b_values = []
        for i in range(len(col_a)):
            if col_a[i] == val_a:
                b_val = col_b[i]
                is_seen = False
                for s in seen_b_values:
                    if s == b_val:
                        is_seen = True
                        break
                if not is_seen:
                    seen_b_values.append(b_val)
        if len(seen_b_values) > 1:
            a_to_b_is_one = False
            break

    # Check mapping from B to A (is it one-to-one or one-to-many?)
    b_to_a_is_one = True
    for val_b in col_b:
        count_a_for_b = 0
        seen_a_values = []
        for i in range(len(col_b)):
            if col_b[i] == val_b:
                a_val = col_a[i]
                is_seen = False
                for s in seen_a_values:
                    if s == a_val:
                        is_seen = True
                        break
                if not is_seen:
                    seen_a_values.append(a_val)
        if len(seen_a_values) > 1:
            b_to_a_is_one = False
            break

    if a_to_b_is_one and b_to_a_is_one:
        return "one-to-one"
    elif a_to_b_is_one and not b_to_a_is_one:
