    else:
        return "many-to-many"

def analyze_column_relationships(data_dict):
    columns = []
    for key in data_dict:
        columns.append(key)

    results = []

    # Iterate through all pairs of columns
    i = 0
    while i < len(columns):
        j = 0
        while j < len(columns):
            if i != j:
                col_name_a = columns[i]
                col_name_b = columns[j]

