def get_unique_count(values):
    unique_list = []
    for val in values:
        is_unique = True
        for existing in unique_list:
            if existing == val:
                is_unique = False
                break
        if is_unique:
            unique_list.append(val)
    return len(unique_list)

def determine_relationship(col_a, col_b):
    # Count total rows
    n_rows = 0
    for _ in col_a:
        n_rows += 1

    # Count unique values in each column
    unique_a = get_unique_count(col_a)
    unique_b = get_unique_count(col_b)

    # Check if mapping from A to B is one-to-one or one-to-many
    # We need to check if any value in A maps to multiple values in B
    a_to_b_multi = False
    for i in range(n_rows):
        val_a = col_a[i]
        val_b_first = None
        for j in range(i + 1, n_rows):
            if col_a[j] == val_a:
                if val_b_first is None:
                    val_b_first = col_b[j]
                elif col_b[j] != val_b_first:
                    a_to_b_multi = True
                    break
        if a_to_b_multi:
            break

    # Check if mapping from B to A is one-to-one or many-to-one (inverse of above)
    b_to_a_multi = False
    for i in range(n_rows):
        val_b = col_b[i]
        val_a_first = None
        for j in range(i + 1, n_rows):
            if col_b[j] == val_b:
                if val_a_first is None:
                    val_a_first = col_a[j]
                elif col_a[j] != val_a_first:
                    b_to_a_multi = True
                    break
        if b_to_a_multi:
            break

    # Determine relationship type
    # If A->B is unique (no multi) and B->A is unique (no multi): one-to-one
    # If A->B is unique but B->A is multi: one-to-many (from A perspective)
    # If A->B is multi but B->A is unique: many-to-one (from A perspective)
    # If both are multi: many-to-many

    if not a_to_b_multi and not b_to_a_multi:
        return "one-2-one"
    elif not a_to_b_multi and b_to_a_multi:
        return "one-2-many"
    elif a_to_b_multi and not b_to_a_multi:
        return "many-2-one"
    else:
        return "many-2-many"

def analyze_column_relationships(data_dict):
    columns = []
    for key in data_dict:
        columns.append(key)

