def filter_max_two(data):
    if not data:
        return []

    num_rows = len(data)
    num_cols = len(data[0])

    # Identify rows with max value 2
    rows_to_zero = []
    for r in range(num_rows):
        current_max = -1
        for c in range(num_cols):
            val = data[r][c]
            if val > current_max:
                current_max = val
        if current_max == 2:
            rows_to_zero.append(r)

    # Identify columns with max value 2
    cols_to_zero = []
    for c in range(num_cols):
        current_max = -1
        for r in range(num_rows):
            val = data[r][c]
            if val > current_max:
                current_max = val
        if current_max == 2:
            cols_to_zero.append(c)

    # Create result matrix
    result = []
    for r in range(num_rows):
        new_row = []
        for c in range(num_cols):
            if r in rows_to_zero or c in cols_to_zero:
                new_row.append(0)
            else:
                new_row.append(data[r][c])
        result.append(new_row)

    return result

