import sys

# Read input from stdin line by line until EOF
lines = []
try:
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        lines.append(line)
except Exception:
    pass

if len(lines) == 0:
    sys.exit(0)

# Parse header
header_line = lines[0].strip()
header_parts = header_line.split()
header_map = {}
for i, h in enumerate(header_parts):
    header_map[h] = i

# Parse data rows into a list of dictionaries
data_rows = []
for line in lines[1:]:
    if not line.strip():
        continue
    parts = line.split()
    row_dict = {}
    for key, idx in header_map.items():
        if idx < len(parts):
            row_dict[key] = parts[idx]
    data_rows.append(row_dict)

# Define group keys and target column
group_keys = ['Sp', 'Mt']
target_col = 'count'

# Helper function to find min value in a list of numbers manually
def find_min_value(numbers_list):
    if len(numbers_list) == 0:
        return None
    min_val = numbers_list[0]
    i = 1
    while i < len(numbers_list):
        current_val = numbers_list[i]
        if current_val < min_val:
            min_val = current_val
        i += 1
    return min_val

# Helper function to get index of first occurrence of a value in a list manually
def find_first_index_of_value(lst, target):
    for i in range(len(lst)):
        if lst[i] == target:
            return i
    return -1

# Group data rows by (Sp, Mt)
groups = {}
for row in data_rows:
    sp_val = row.get('Sp', '')
    mt_val = row.get('Mt', '')
    group_key = (sp_val, mt_val)

    if group_key not in groups:
        groups[group_key] = []

    # Extract count value for this row
    count_val = row.get(target_col, 0)
    # Ensure we treat it as a number for comparison. 
    # Since input is text, we assume valid integers based on problem context.
    try:
        num_count = int(count_val)
    except ValueError:
        num_count = 0

    groups[group_key].append({
        'row': row,
        'count_num': num_count
    })

# Find the minimum count for each group and collect matching rows
result_rows = []

for group_key, items in groups.items():
    if len(items) == 0:
        continue

    # Extract all count numbers to find the min
    counts_list = []
    for item in items:
        counts_list.append(item['count_num'])

    min_count = find_min_value(counts_list)

    if min_count is None:
        continue

    # Find all rows where count equals min_count
    for item in items:
        if item['count_num'] == min_count:
            result_rows.append(item['row'])

# Output the result
if len(result_rows) > 0:
    # Reconstruct header string
    output_header = ' '.join(header_parts) + '\n'
    sys.stdout.write(output_header)

    for row in result_rows:
        values = []
        for h in header_parts:
            val = row.get(h, '')
            values.append(str(val))
        sys.stdout.write(' '.join(values) + '\n')
else:
    # If no rows match (e.g., empty input after header), just print header if it exists or nothing
    if len(lines) > 0:
        output_header = ' '.join(header_parts) + '\n'
        sys.stdout.write(output_header)

