}

def parse_date(date_str):
    parts = date_str.split('/')
    day = int(parts[0])
    month = int(parts[1])
    year = int(parts[2])
    if year < 50:
        year += 2000
    else:
        year += 1900
    return (year, month, day)

def format_date(year, month, day):
    return "{:04d}-{:02d}-{:02d}".format(year, month, day)

rows = []
for i in range(len(data['Date'])):
    date_str = data['Date'][i]
    val = data['Val'][i]
    year, month, day = parse_date(date_str)
    rows.append({
        'original_index': i,
        'year': year,
        'month': month,
        'day': day,
        'date_str': format_date(year, month, day),
        'val': val
    })

def count_occurrences(rows, key_func):
    counts = {}
    for row in rows:
        key = key_func(row)
        if key in counts:
            counts[key] += 1
        else:
            counts[key] = 1
    return counts

day_key = lambda r: (r['year'], r['month'], r['day'])
month_key = lambda r: (r['year'], r['month'])
year_key = lambda r: (r['year'])

