    key_d = (row['year'], row['month'], row['day'])
    key_m = (row['year'], row['month'])
    key_y = (row['year'])
    row['Count_d'] = day_counts[key_d]
    row['Count_m'] = month_counts[key_m]
    row['Count_y'] = year_counts[key_y]

rows_sorted = []
for i in range(len(rows)):
    min_idx = i
    for j in range(i + 1, len(rows)):
        if rows[j]['original_index'] < rows[min_idx]['original_index']:
            min_idx = j
    temp = rows[i]
    rows[i] = rows[min_idx]
    rows[min_idx] = temp

print("Date       Val Count_d Count_m Count_y")
for row in rows:
    print("{:<10} {:<3} {:>7} {:>7} {:>7}".format(row['date_str'], row['val'], row['Count_d'], row['Count_m'], row['Count_y']))

