class DataFrame:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        if self.rows > 0:
            self.columns = list(data[0].keys())
        else:
            self.columns = []

    def get_row(self, index):
        return self.data[index]

    def get_column_values(self, col_name):
        values = []
        for i in range(self.rows):
            row = self.get_row(i)
            values.append(row[col_name])
        return values

    def group_by_key(self, key_col):
        groups = {}
        for i in range(self.rows):
            row = self.get_row(i)
            key_val = row[key_col]
            if key_val not in groups:
                groups[key_val] = []
            groups[key_val].append(i)
        return groups

    def count_condition(self, group_indices, target_value, condition_col):
        count = 0
        for idx in group_indices:
            row = self.get_row(idx)
            if row[condition_col] == target_value:
                count += 1
        return count

    def process(self, key_col, condition_col, target_value):
        groups = self.group_by_key(key_col)
        result_rows = []

        # Sort keys manually
        sorted_keys = []
        for k in groups.keys():
            sorted_keys.append(k)

        # Manual sort of sorted_keys
        n = len(sorted_keys)
        for i in range(n):
            for j in range(i + 1, n):
                if sorted_keys[i] > sorted_keys[j]:
                    temp = sorted_keys[i]
                    sorted_keys[i] = sorted_keys[j]
                    sorted_keys[j] = temp

        for k in sorted_keys:
            indices = groups[k]
            cnt = self.count_condition(indices, target_value, condition_col)
            result_rows.append({'key1': k, 'count': cnt})

        return DataFrame(result_rows)

# Input data construction without external libraries
