    {"key1": "c", "key2": "two"}
]

# Step 1: Extract unique keys from key1 manually
unique_keys = []
for row in data:
    is_new = True
    for existing_key in unique_keys:
        if existing_key == row["key1"]:
            is_new = False
            break
    if is_new:
        unique_keys.append(row["key1"])

# Step 2: Initialize result list
result_rows = []

# Step 3: Iterate through each unique key and count occurrences of "two" in key2
for key in unique_keys:
    count = 0
    for row in data:
        if row["key1"] == key:
            if row["key2"] == "two":
                count = count + 1
    result_rows.append({"key1": key, "count": count})

# Step 4: Sort the result by key1 manually (Bubble Sort)
n = len(result_rows)
for i in range(n):
    for j in range(0, n - i - 1):
        if result_rows[j]["key1"] > result_rows[j + 1]["key1"]:
            temp = result_rows[j]
            result_rows[j] = result_rows[j + 1]
            result_rows[j + 1] = temp

# Output the result (simulating a dataframe print)
print("  key1  count")
for i, row in enumerate(result_rows):
    print(str(i) + "   " + row["key1"] + "     " + str(row["count"]))

