def split_string_after_last_underscore(s):
    if not isinstance(s, str):
        return s
    result = []
    i = 0
    while i < len(s):
        if s[i] == '_':
            # Check if this is the last underscore
            j = i + 1
            while j < len(s) and s[j] != '_':
                j += 1
            if j == len(s):
                # This is the last underscore, take everything before it
                for k in range(i):
                    result.append(s[k])
                break
        i += 1

    return ''.join(result)

