class DataFrame:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        if self.rows == 0:
            return
        self.columns = list(data[0].keys())
        self.index_values = [row[0] for row in data]

    def get_column(self, name):
        result = []
        for row in self.data:
            result.append(row[name])
        return result

    def group_by_key(self, key_name):
        groups = {}
        for i in range(self.rows):
            val = self.index_values[i]
            if val not in groups:
                groups[val] = []
            groups[val].append(i)
        return groups

    def bin_views(self, views_list, bins):
        # bins is a list of numbers defining the edges: [1, 10, 25, 50, 100]
        # This creates intervals (1, 10], (10, 25], etc.
        num_bins = len(bins) - 1
        bin_counts = {}

        for i in range(self.rows):
            view_val = views_list[i]
            username = self.index_values[i]

            if username not in bin_counts:
                bin_counts[username] = [0] * num_bins

            # Find which bin this value falls into
            found_bin = -1
            for b_idx in range(num_bins):
                lower = bins[b_idx]
                upper = bins[b_idx + 1]
                if view_val > lower and view_val <= upper:
                    found_bin = b_idx
                    break

            if found_bin != -1:
                bin_counts[username][found_bin] += 1

        return bin_counts

    def print_pivot_table(self, bins):
        num_bins = len(bins) - 1
        groups = self.group_by_key("username")
        views_list = self.get_column("views")

        # Initialize the table structure
        # We will store counts in a nested list: table[username][bin_index]
        table = {}
        for username in groups.keys():
            table[username] = [0] * num_bins

        # Fill the table
        for username, indices in groups.items():
            for idx in indices:
                view_val = views_list[idx]

                # Find bin manually
                found_bin = -1
                for b_idx in range(num_bins):
                    lower = bins[b_idx]
                    upper = bins[b_idx + 1]
                    if view_val > lower and view_val <= upper:
                        found_bin = b_idx
                        break

                if found_bin != -1:
                    table[username][found_bin] += 1

        # Print header
        print("views", end="")
        for b_idx in range(num_bins):
            lower = bins[b_idx]
            upper = bins[b_idx + 1]
            print(f" ({lower}, {upper}]", end="")
        print()

        # Print rows
        # Sort usernames manually (simple bubble sort)
        sorted_usernames = list(table.keys())
        n_users = len(sorted_usernames)
        for i in range(n_users):
            for j in range(0, n_users - 1 - i):
                if sorted_usernames[j] > sorted_usernames[j + 1]:
                    temp = sorted_usernames[j]
                    sorted_usernames[j] = sorted_usernames[j + 1]
                    sorted_usernames[j + 1] = temp

        for username in sorted_usernames:
            print(username, end="")
            counts = table[username]
            for count in counts:
                print(f"{count:<10}", end="")
            print()


