def manual_bubble_sort(lst):
    n = len(lst)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if lst[j][0] > lst[j + 1][0]:
                temp = lst[j]
                lst[j] = lst[j + 1]
                lst[j + 1] = temp
                swapped = True
        if not swapped:
            break
    return lst

def manual_groupby_and_aggregate(data_rows, group_col_idx, time_col_idx, amount_col_idx):
    unique_users = []

    for row in data_rows:
        user_id = row[group_col_idx]
        found = False
        for i in range(len(unique_users)):
            if unique_users[i] == user_id:
