def manual_filter_dataframe(df_dict, index_levels, filt_series):
    """
    Manually filters a dictionary-based dataframe representation using a boolean series
    aligned with a specific higher-level index.

    Args:
        df_dict (dict): A dictionary representing the dataframe rows. 
                        Keys are tuples of index values, values are dicts of column data.
                        Example: {(1, 1): {'c': 0}, (1, 2): {'c': 1}, ...}
        index_levels (int): The number of levels in the multi-index (e.g., 2 for 'a' and 'b').
        filt_series (dict): A dictionary representing the filter series.
                            Keys are the values of the first index level, values are booleans.
                            Example: {1: True, 2: False, 3: True}

    Returns:
        dict: The filtered dataframe representation.
    """
    result = {}

    # Iterate through all rows in the input dataframe dictionary
    for index_key, row_data in df_dict.items():
        # Extract the value of the first level of the index (level 'a')
        # We assume the index_key is a tuple and we want the first element.
        if not isinstance(index_key, tuple):
            # Handle case where index might be a single value if levels=1
            current_level_value = index_key
        else:
            current_level_value = index_key[0]

        # Check if this level value exists in the filter series
        is_in_filter = False
        for filt_key in filt_series:
            if filt_key == current_level_value:
                is_in_filter = True
                break

        if not is_in_filter:
            continue

        # Get the boolean value from the filter series
        filter_bool = None
        for filt_key, filt_val in filt_series.items():
            if filt_key == current_level_value:
                filter_bool = filt_val
                break

        # If the filter value is True, keep the row
        if filter_bool is True:
            result[index_key] = row_data

    return result


def manual_create_dataframe(data_dict):
    """
    Helper to create a dictionary-based dataframe from lists.
    Mimics pd.DataFrame(...).set_index(...) behavior manually.
    """
    # data_dict structure: {'a': [...], 'b': [...], 'c': [...]}
    keys = list(data_dict.keys())
    if len(keys) < 2:
        return {}

    index_col_1_name = keys[0]
    index_col_2_name = keys[1]
    value_cols = keys[2:]

    # Determine length of data
    length = -1
    for k in keys:
        if len(data_dict[k]) > length:
            length = len(data_dict[k])

    result = {}

    i = 0
    while i < length:
        idx_val_1 = data_dict[index_col_1_name][i]
        idx_val_2 = data_dict[index_col_2_name][i]

        row_data = {}
        for col in value_cols:
            row_data[col] = data_dict[col][i]

        result[(idx_val_1, idx_val_2)] = row_data
        i += 1

    return result


def manual_print_dataframe(df_dict):
    """
    Helper to print the dataframe in a readable format.
    """
    # Sort keys manually for consistent output
    sorted_keys = []
    for k in df_dict:
        inserted = False
        j = 0
        while j < len(sorted_keys):
            if k[0] < sorted_keys[j][0]:
                sorted_keys.insert(j, k)
                inserted = True
                break
            elif k[0] == sorted_keys[j][0]:
                if k[1] < sorted_keys[j][1]:
                    sorted_keys.insert(j, k)
                    inserted = True
                    break
                else:
                    j += 1
            else:
                j += 1
        if not inserted:
            sorted_keys.append(k)

    print("     c")
    print("a b   ")

    for key in sorted_keys:
        row_data = df_dict[key]
        val_c = row_data['c']
        print(f"{key[0]} {key[1]}  {val_c}")


