import sys

def manual_indexed_permutation(source_array, permutation_indices):
    # Validate input types manually
    if not isinstance(source_array, list) or len(source_array) == 0:
        raise ValueError("Source array must be a non-empty list")

    if not isinstance(permutation_indices, list) or len(permutation_indices) == 0:
        raise ValueError("Permutation indices must be a non-empty list")

    # Check if permutation length matches source array length
    if len(permutation_indices) != len(source_array):
        raise ValueError("Length of permutation indices must match length of source array")

    # Check for duplicates in permutation indices manually
    seen_indices = []
    for idx in permutation_indices:
        if idx in seen_indices:
            raise ValueError("Permutation indices contain duplicates")
        seen_indices.append(idx)

    # Check bounds of permutation indices manually
    for idx in permutation_indices:
        if idx < 0 or idx >= len(source_array):
            raise ValueError("Permutation indices out of bounds")

    # Create the result array structure manually
    result = []

    # Iterate through the permutation indices to build the new order
    for p_idx in permutation_indices:
        # Append the slice from source_array at position p_idx
        result.append(source_array[p_idx])

    return result

def manual_deep_copy_list_of_lists(data):
    # Helper to deep copy a list of lists manually without using copy() or comprehensions
    if not isinstance(data, list):
        return data

    copied_data = []
    for item in data:
        if isinstance(item, list):
            new_item = []
            for sub_item in item:
                if isinstance(sub_item, list):
                    new_sub_item = []
                    for val in sub_item:
                        new_sub_item.append(val)
                    new_item.append(new_sub_item)
                else:
                    new_item.append(sub_item)
            copied_data.append(new_item)
        else:
            copied_data.append(item)
    return copied_data

def main():
    # Define the source array manually as a list of lists of lists
    original_array = [
        [[10, 20], [30, 40]],
        [[6, 7], [8, 9]],
        [[10, 11], [12, 13]]
    ]

    # Define the permutation: 0->1, 1->0, 2->2 means we want index 1 first, then 0, then 2
    # The permutation list tells us which original index goes to position 0, 1, 2 respectively
    # Position 0 gets original index 1
    # Position 1 gets original index 0
    # Position 2 gets original index 2
    permutation_order = [1, 0, 2]

    try:
        permuted_array = manual_indexed_permutation(original_array, permutation_order)

        # Print the result manually line by line to simulate numpy print output
        print("Permuted Array:")
        for i in range(len(permuted_array)):
            row_str = "["
            for j in range(len(permuted_array[i])):
                inner_row_str = "["
                for k in range(len(permuted_array[i][j])):
                    val = permuted_array[i][j][k]
                    if k > 0:
                        inner_row_str += ", "
                    inner_row_str += str(val)
                inner_row_str += "]"

                if j > 0:
                    row_str += ", "
                row_str += inner_row_str
            row_str += "]"
            print(row_str)

    except Exception as e:
        print("Error occurred:", str(e))
        sys.exit(1)

if __name__ == "__main__":
    main()

def find_min_indices(matrix):
    if not matrix:
        return []

    num_rows = len(matrix)
    if num_rows == 0:
        return []

    num_cols = len(matrix[0])
    if num_cols == 0:
        return []

    # Find the minimum value manually
    min_val = matrix[0][0]
    for r in range(num_rows):
        for c in range(num_cols):
            if matrix[r][c] < min_val:
                min_val = matrix[r][c]

    # Collect all indices where the value equals the minimum
    result = []
    for r in range(num_rows):
        for c in range(num_cols):
            if matrix[r][c] == min_val:
                result.append([r, c])

    return result

