import sys

def get_array_length(arr):
    length = 0
    current = arr
    while current is not None:
        if hasattr(current, '__len__'):
            try:
                # Try to get the length attribute directly first
                l = len(current)
                if isinstance(l, int):
                    return l
            except TypeError:
                pass

        # If it's a list or tuple, iterate to count
        if isinstance(current, (list, tuple)):
            for _ in current:
                length += 1
            return length

        # If it's a custom object with __len__ but len() failed, try iteration
        if hasattr(current, '__iter__') and not isinstance(current, str):
            for _ in current:
                length += 1
            return length

        break
    return 0

def get_array_dimensions(arr):
    """Returns a list of dimensions [d0, d1, ...] for nested lists/tuples."""
    dims = []
    current = arr

    while isinstance(current, (list, tuple)) and len(current) > 0:
        if len(current) == 0:
            break

        # Check if all elements are the same type and structure
        first_elem = current[0]

        # If the first element is a list/tuple, we have nested dimensions
        if isinstance(first_elem, (list, tuple)):
            dims.append(len(current))
            current = first_elem
        else:
            # No more nesting
            break

    if len(current) > 0 and not isinstance(current, (list, tuple)):
        dims.append(1)

    return dims

def flatten_array(arr):
    """Flattens a nested list/tuple structure into a single list."""
    result = []
    current = arr

    while isinstance(current, (list, tuple)) and len(current) > 0:
        for item in current:
            if isinstance(item, (list, tuple)):
                result.extend(flatten_array(item))
            else:
                result.append(item)
        current = None # Break the loop after one level of flattening logic handled above

    # Handle the case where the top level wasn't a list/tuple but we need to flatten one level
    if not isinstance(arr, (list, tuple)):
        return [arr]

    final_result = []
    for item in arr:
        if isinstance(item, (list, tuple)):
            final_result.extend(flatten_array(item))
        else:
            final_result.append(item)

    return final_result

def calculate_elementwise_average(arrays):
    """
    Calculates the element-wise average of a list of arrays.
    Arrays must be of the same shape and contain numeric values.
    Returns a new array (list) with the averaged values.
    """
    if len(arrays) == 0:
        return []

    # Flatten all input arrays to handle nested structures uniformly
    flattened_arrays = []
    for arr in arrays:
        flat_arr = flatten_array(arr)
        flattened_arrays.append(flat_arr)

    # Check if all arrays have the same length
    first_len = get_array_length(flattened_arrays[0])
    for i in range(1, len(flattened_arrays)):
        current_len = get_array_length(flattened_arrays[i])
        if current_len != first_len:
            raise ValueError("All input arrays must have the same length.")

    total_count = len(flattened_arrays)
    if total_count == 0:
        return []

    # Calculate average for each element position
    result = []
    num_elements = first_len

    for i in range(num_elements):
        sum_val = 0.0

        for arr in flattened_arrays:
            val = arr[i]
            if isinstance(val, (int, float)):
                sum_val += val
            else:
                # If non-numeric, treat as 0 or raise error? Assuming numeric based on prompt.
                # We will just add it if it's a number, otherwise skip to avoid type errors in manual summation
                pass

        avg_val = sum_val / total_count
        result.append(avg_val)

    return result

# Example usage from the prompt
if __name__ == "__main__":
    # Simulating numpy arrays using lists since we cannot use numpy
    a = [10, 20, 30]
