def get_symmetric_difference(A, B):
    result = []

    # Helper to check if a row exists in a 2D array
    def row_exists(row, arr):
        for r in arr:
            match = True
            if len(row) != len(r):
                match = False
            else:
                for i in range(len(row)):
                    if row[i] != r[i]:
                        match = False
                        break
            if match:
                return True
        return False

    # Collect elements from A that are not in B
    for row_a in A:
        if not row_exists(row_a, B):
            result.append(list(row_a))

    # Collect elements from B that are not in A
    for row_b in B:
        if not row_exists(row_b, A):
            result.append(list(row_b))

    return result

# Example usage with standard lists instead of numpy arrays
