def create_initial_array():
    row1 = [1, 2]
    row2 = [3, 4]
    return [row1, row2]

def insert_row_at_index(matrix, index, new_row):
    if index < 0:
        index = 0
    if index > len(matrix):
        index = len(matrix)

    result_matrix = []
    i = 0

    while i < len(matrix):
        if i == index:
            result_matrix.append(new_row)
        result_matrix.append(matrix[i])
        i = i + 1

    return result_matrix

def print_matrix(matrix):
    for row in matrix:
        output_str = ""
        j = 0
        while j < len(row):
            if j > 0:
                output_str = output_str + ", "
            output_str = output_str + str(row[j])
            j = j + 1
        print(output_str)

def main():
    original_array = create_initial_array()

    # Simulating the user's request to insert [3, 5] at index 1 (between [1,2] and [3,4])
    row_to_insert = [3, 5]
    insertion_index = 1

    modified_array = insert_row_at_index(original_array, insertion_index, row_to_insert)

    print("Original array:")
    print_matrix(original_array)

    print("\nModified array after inserting [3, 5] at index 1:")
    print_matrix(modified_array)

if __name__ == "__main__":
    main()

