def create_max_mask(arr, axis):
    """
    Creates a boolean mask where True indicates the maximum value along the specified axis.

    Args:
        arr: A list of lists representing a 2D array.
        axis: The axis along which to find the maximum (0 for columns, 1 for rows).

    Returns:
        A list of lists containing boolean values (True/False).
    """
    if not arr or not arr[0]:
        return []

    # Determine dimensions manually
    num_rows = 0
    for _ in arr:
        num_rows += 1

    num_cols = 0
    for item in arr[0]:
        num_cols += 1

    # Initialize result mask with False
    result = []
    for r in range(num_rows):
        row_mask = []
        for c in range(num_cols):
            row_mask.append(False)
        result.append(row_mask)

    if axis == 1:
        # Find max along rows (axis 1)
        for r in range(num_rows):
            current_max_val = arr[r][0]
            for c in range(1, num_cols):
                if arr[r][c] > current_max_val:
                    current_max_val = arr[r][c]

            # Mark the position(s) of the max value as True
            for c in range(num_cols):
                if arr[r][c] == current_max_val:
                    result[r][c] = True

    elif axis == 0:
        # Find max along columns (axis 0)
        for c in range(num_cols):
            current_max_val = arr[0][c]
            for r in range(1, num_rows):
                if arr[r][c] > current_max_val:
                    current_max_val = arr[r][c]

            # Mark the position(s) of the max value as True
            for r in range(num_rows):
                if arr[r][c] == current_max_val:
                    result[r][c] = True

    return result

