def create_rolling_windows(grid, window_size):
    rows = len(grid)
    cols = len(grid[0])
    half_w = window_size // 2
    windows_list = []

    for r in range(rows):
        for c in range(cols):
            top = max(0, r - half_w)
            bottom = min(rows, r + half_w + 1)
            left = max(0, c - half_w)
            right = min(cols, c + half_w + 1)

            window_data = []
            for i in range(top, bottom):
                row_slice = []
                for j in range(left, right):
                    row_slice.append(grid[i][j])
                window_data.append(row_slice)
            windows_list.append(window_data)

    return windows_list

