def manual_min_max_scaler_2d(data):
    if not data:
        return []

    # Flatten the 2D list manually to find global min and max
    flat_values = []
    for row in data:
        for val in row:
            flat_values.append(val)

    # Find global minimum manually
    global_min = flat_values[0]
    for i in range(1, len(flat_values)):
        if flat_values[i] < global_min:
            global_min = flat_values[i]

    # Find global maximum manually
    global_max = flat_values[0]
    for i in range(1, len(flat_values)):
        if flat_values[i] > global_max:
            global_max = flat_values[i]

    # Handle case where all values are the same (avoid division by zero)
    range_val = global_max - global_min
    if range_val == 0:
        return [[0.0 for _ in row] for row in data]

    # Normalize the entire array
    result = []
    for row in data:
        new_row = []
        for val in row:
            normalized_val = (val - global_min) / range_val
            new_row.append(normalized_val)
        result.append(new_row)

    return result

