def manual_min(lst):
    if len(lst) == 0:
        return float('inf')
    current_min = lst[0]
    for i in range(1, len(lst)):
        if lst[i] < current_min:
            current_min = lst[i]
    return current_min

def manual_count_nonzero(arr):
    count = 0
    for val in arr:
        if val != 0.0:
            count += 1
    return count

def are_close(a, b, rel_tol=1e-9, abs_tol=0.0):
    # Handle NaN cases: NaN is equal to NaN
    if a != a and b != b:
        return True
    # If one is NaN and the other is not, they are not close
    if a != a or b != b:
        return False

    diff = abs(b - a)

    # Check absolute tolerance first
    if diff <= abs_tol:
        return True

    # Check relative tolerance
    max_val = manual_max([a, b])
    min_val = manual_min([a, b])

    if max_val == 0.0:
        return False

    rel_diff = diff / max_val
    return rel_diff <= rel_tol

def count_truly_different(s1, s2):
    n = len(s1)
    if len(s2) != n:
        return -1 # Error case

    different_count = 0

    for i in range(n):
        val1 = s1[i]
        val2 = s2[i]

        if not are_close(val1, val2):
            different_count += 1

    return different_count

def main():
    # Simulate the scenario described in the prompt without using numpy for data generation logic
    # We will manually create two arrays that represent the same values in different orders
    # to demonstrate the counting function.

    # Let's create a simple test case where we know the sums should be equal but floating point might differ
    # due to order of addition, though in this specific small integer-like float example it might not happen.
    # To force the issue, we can use larger numbers or more terms.

    # Generating data manually without numpy
    n = 10
    m = 4

    # Create a list of floats
    tag_list = []
    for i in range(n):
        row = []
        for j in range(m):
            # Using a deterministic pseudo-random approach or just fixed values for reproducibility
            # Since we can't use random without numpy, let's use a simple formula based on indices
            val = (i * 100 + j) / 100.0
            row.append(val)
        tag_list.append(row)

    # Calculate s1 manually
    s1 = []
    for i in range(n):
        row_sum = manual_sum(tag_list[i])
        s1.append(row_sum)

    # Calculate s2 (reversed columns) manually
    s2 = []
    for i in range(n):
        reversed_row = tag_list[i][::-1]
        row_sum = manual_sum(reversed_row)
        s2.append(row_sum)

    # Count truly different elements
    diff_count = count_truly_different(s1, s2)

    print(diff_count)

if __name__ == "__main__":
    main()

import sys

def read_array_from_file(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(',')
            row = []
            for part in parts:
                try:
                    val = float(part)
                    row.append(val)
                except ValueError:
                    pass
            data.append(row)
    return data

def find_max_shape(array_list):
    max_rows = 0
    max_cols = 0
    for arr in array_list:
        if len(arr) > max_rows:
            max_rows = len(arr)
        for row in arr:
            if len(row) > max_cols:
                max_cols = len(row)
    return (max_rows, max_cols)

def pad_array_to_shape(array, target_shape):
    target_rows, target_cols = target_shape
    current_rows = len(array)
    current_cols = 0
    for row in array:
        if len(row) > current_cols:
            current_cols = len(row)

    padded_array = []
    rows_to_add = target_rows - current_rows

    for i in range(current_rows):
        new_row = []
        original_row = array[i]
        cols_to_add = target_cols - len(original_row)

        for j in range(len(original_row)):
            new_row.append(original_row[j])

        while len(new_row) < target_cols:
            new_row.append(0.0)

        padded_array.append(new_row)

    while len(padded_array) < target_rows:
        new_row = []
        for _ in range(target_cols):
            new_row.append(0.0)
        padded_array.append(new_row)

    return padded_array

def write_padded_arrays_to_file(array_list, output_filename):
    max_shape = find_max_shape(array_list)

    with open(output_filename, 'w') as f:
        for arr in array_list:
            padded_arr = pad_array_to_shape(arr, max_shape)

            for row_idx, row in enumerate(padded_arr):
                line_parts = []
                for val in row:
                    line_parts.append(str(val))
                f.write(','.join(line_parts) + '\n')

def main():
    input_filename = 'input.txt'
    output_filename = 'output_padded.txt'

    array_list = read_array_from_file(input_filename)
    write_padded_arrays_to_file(array_list, output_filename)
    print("Padding complete. Output written to " + output_filename)

if __name__ == "__main__":
    main()

import numpy as np

def crop_zeros(image):
    # Convert input to numpy array if it isn't already, though the prompt implies it is
    arr = image

    rows = len(arr)
    cols = len(arr[0])

    # Initialize top and bottom boundaries
    top = 0
    bottom = rows - 1

    # Initialize left and right boundaries
    left = 0
    right = cols - 1

    # Find the first row from the top that contains a non-zero value
    while top <= bottom:
        current_row = arr[top]
        has_non_zero = False
        for val in current_row:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            top += 1
        else:
            break

    # Find the first row from the bottom that contains a non-zero value
    while bottom >= top:
        current_row = arr[bottom]
        has_non_zero = False
        for val in current_row:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            bottom -= 1
        else:
            break

    # Find the first column from the left that contains a non-zero value
    while left <= right:
        current_col = []
        for r in range(rows):
            current_col.append(arr[r][left])

        has_non_zero = False
        for val in current_col:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            left += 1
        else:
            break

    # Find the first column from the right that contains a non-zero value
    while right >= left:
        current_col = []
        for r in range(rows):
            current_col.append(arr[r][right])

        has_non_zero = False
        for val in current_col:
            if val != 0:
                has_non_zero = True
                break

        if not has_non_zero:
            right -= 1
        else:
            break

    # Extract the sub-array based on calculated boundaries
    result = []
    for r in range(top, bottom + 1):
        new_row = []
        for c in range(left, right + 1):
            new_row.append(arr[r][c])
        result.append(new_row)

    return result

# Example usage with the provided data
