import torch

def manual_index_select(tensor, indices):
    result_rows = []
    for row_idx in range(len(tensor)):
        current_row = tensor[row_idx]
        selected_values = []
        for idx_val in indices:
            if 0 <= idx_val < len(current_row):
                selected_values.append(current_row[idx_val])
        result_rows.append(selected_values)
    return torch.LongTensor(result_rows)

