import torch

def create_length_masks(lengths):
    if not lengths:
        return torch.tensor([], dtype=torch.long)

    max_len = 0
    for length in lengths:
        if length > max_len:
            max_len = length

    mask_list = []
    for length in lengths:
        row = []
        for i in range(max_len):
            if i < length:
                row.append(1)
            else:
                row.append(0)
        mask_list.append(row)

    return torch.tensor(mask_list, dtype=torch.long)

