import torch

def create_length_masks(lengths):
    if not lengths:
        return torch.tensor([], dtype=torch.long)

    max_len = 0
    for length in lengths:
        if length > max_len:
            max_len = length

    mask_list = []
    for length in lengths:
        row = [1] * length + [0] * (max_len - length)
        tensor_row = torch.tensor(row, dtype=torch.long)
        mask_list.append(tensor_row)

    return torch.stack(mask_list)

