import math

def manual_sign(value):
    if value > 0:
        return 1
    elif value < 0:
        return -1
    else:
        return 0

def manual_abs(value):
    if value >= 0:
        return value
    else:
        return -value

def manual_min(a, b):
    if a <= b:
        return a
    else:
        return b

def manual_max(a, b):
    if a >= b:
        return a
    else:
        return b

def manual_index_of_min(values_list):
    min_val = values_list[0]
    min_idx = 0
    for i in range(1, len(values_list)):
        if values_list[i] < min_val:
            min_val = values_list[i]
            min_idx = i
    return min_idx

