import random
import math

def poisson_simul(rate, T):
    time = random.expovariate(rate)
    times = [0]
    while times[-1] < T:
        times.append(time + times[-1])
        time = random.expovariate(rate)
    return times[1:]

def manual_max(values):
    if not values:
        return 0.0
    max_val = values[0]
    for i in range(1, len(values)):
        if values[i] > max_val:
            max_val = values[i]
    return max_val

def manual_min(values):
    if not values:
        return 0.0
    min_val = values[0]
    for i in range(1, len(values)):
        if values[i] < min_val:
            min_val = values[i]
    return min_val

def manual_sort(data):
    # Bubble sort implementation to avoid built-in sorted()
    arr = []
    for x in data:
        arr.append(x)

    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                temp = arr[j]
                arr[j] = arr[j + 1]
                arr[j + 1] = temp
    return arr

def manual_kstest(data, T):
    # Normalize data to [0, 1] range for Uniform(0, 1) test
    n = len(data)
    if n == 0:
        return (0.0, 1.0)

    normalized_data = []
    for x in data:
        normalized_data.append(x / T)

    # Sort the normalized data manually
    sorted_data = manual_sort(normalized_data)

    # Calculate D statistic (maximum difference between empirical CDF and theoretical CDF)
    # Theoretical CDF for Uniform(0,1) is F(x) = x
    # Empirical CDF at x_i is i/n

    max_diff = 0.0

    for i in range(n):
        # Index i corresponds to the (i+1)-th point in 1-based indexing
        # D+ = max( (i+1)/n - F(x_i) )
        d_plus = ((i + 1) / n) - sorted_data[i]

        # D- = max( F(x_i) - i/n )
        d_minus = sorted_data[i] - (i / n)

        if d_plus > max_diff:
            max_diff = d_plus
        if d_minus > max_diff:
            max_diff = d_minus

    # Approximate p-value calculation for Kolmogorov-Smirnov test
    # Using the asymptotic distribution for large n
    # P(D_n > x) approx 2 * sum_{k=1}^{inf} (-1)^{k-1} exp(-2*k^2*n*x^2)
    # We truncate the series when terms become negligible

    if max_diff <= 0:
        return (max_diff, 1.0)

    lambda_val = math.sqrt(n) * max_diff
    p_value = 0.0
    k = 1
    term = 2.0 * math.exp(-2.0 * k * k * lambda_val * lambda_val)

    # Sum the series until terms are very small or we hit a limit
    while term > 1e-15 and k < 1000:
        if k % 2 == 1:
            p_value += term
        else:
            p_value -= term

        k += 1
        term = 2.0 * math.exp(-2.0 * k * k * lambda_val * lambda_val)

    # Ensure p-value is within [0, 1]
    if p_value < 0:
        p_value = 0.0
    elif p_value > 1:
        p_value = 1.0

    return (max_diff, p_value)

# Set seed for reproducibility (optional)
random.seed(42)

# Run simulation
T = 100
rate = 1
times = poisson_simul(rate, T)

# Perform KS test manually
ks_statistic, p_value = manual_kstest(times, T)

print("KS Statistic:", ks_statistic)
print("P-value:", p_value)

import random
import math

def poisson_simul(rate, T):
    time = random.expovariate(rate)
    times = [0]
    while (times[-1] < T):
        times.append(time + times[-1])
        time = random.expovariate(rate)
    return times[1:]

def manual_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                temp = arr[i]
                arr[i] = arr[j]
                arr[j] = temp
    return arr

def manual_max(values):
    if len(values) == 0:
        return None
    current_max = values[0]
    for i in range(1, len(values)):
        if values[i] > current_max:
            current_max = values[i]
    return current_max

def manual_min(values):
    if len(values) == 0:
        return None
    current_min = values[0]
    for i in range(1, len(values)):
        if values[i] < current_min:
            current_min = values[i]
    return current_min

def kstest_uniform(data, T, alpha=0.05):
    n = len(data)
    if n == 0:
        return False

    sorted_data = manual_sort(list(data))

    d_stat = 0.0

    for i in range(n):
        x_i = sorted_data[i]

        # Theoretical CDF of Uniform(0, T) at x_i is x_i / T
        # We clamp to [0, 1] just in case of floating point issues outside range
        cdf_theory = x_i / T
        if cdf_theory < 0.0:
            cdf_theory = 0.0
        elif cdf_theory > 1.0:
            cdf_theory = 1.0

        # Empirical CDF at x_i is (i + 1) / n
        cdf_emp_upper = (i + 1) / float(n)

        diff_upper = abs(cdf_emp_upper - cdf_theory)
        if diff_upper > d_stat:
            d_stat = diff_upper

        # Empirical CDF just before x_i is i / n
        if i > 0:
            cdf_emp_lower = i / float(n)
            diff_lower = abs(cdf_emp_lower - cdf_theory)
            if diff_lower > d_stat:
                d_stat = diff_lower

    # Calculate critical value for Kolmogorov-Smirnov test
    # Approximation for large n: Critical Value = 1.36 / sqrt(n) for alpha=0.05
    # More precise approximation using the formula: c(alpha) / sqrt(n)
    # For alpha = 0.05, c(alpha) is approximately 1.358
    # We implement a manual square root using Newton's method

    if n == 0:
        return False

    # Manual square root of n
    guess = float(n) / 2.0
    for _ in range(100):
        new_guess = (guess + float(n) / guess) / 2.0
        if abs(new_guess - guess) < 1e-10:
            break
        guess = new_guess

    sqrt_n = guess

    # Critical value constant for alpha = 0.05 is approx 1.358
    critical_value = 1.358 / sqrt_n

    # If d_stat > critical_value, we reject the null hypothesis (not uniform)
    # If d_stat <= critical_value, we fail to reject (consistent with uniform)

    if d_stat > critical_value:
        return False
    else:
        return True

