def count_regions(grid, threshold):
    visited = []
    for _ in range(512):
        row = []
        for _ in range(512):
            row.append(False)
        visited.append(row)

    region_count = 0

    def get_neighbors(x, y):
        neighbors = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx = x + dx
                ny = y + dy
                if 0 <= nx < 512 and 0 <= ny < 512:
                    neighbors.append((nx, ny))
        return neighbors

    def flood_fill(start_x, start_y):
        stack = [(start_x, start_y)]
        while len(stack) > 0:
            curr_x, curr_y = stack[-1]
            stack.pop()

            if visited[curr_y][curr_x]:
                continue

            if grid[curr_y][curr_x] <= threshold:
                continue

            visited[curr_y][curr_x] = True

            neighbors = get_neighbors(curr_x, curr_y)
            for nx, ny in neighbors:
                stack.append((nx, ny))

    for y in range(512):
        for x in range(512):
            if not visited[y][x]:
                if grid[y][x] > threshold:
                    region_count += 1
                    flood_fill(x, y)

    return region_count

