import numpy as np

def get_unique_ids(arr):
    unique_ids = []
    rows = len(arr)
    cols = len(arr[0]) if rows > 0 else 0

    for r in range(rows):
        for c in range(cols):
            val = arr[r][c]
            found = False
            for uid in unique_ids:
                if uid == val:
                    found = True
                    break
            if not found and val != 0:
                unique_ids.append(val)
    return unique_ids

def get_coords_for_id(arr, target_id):
    coords = []
    rows = len(arr)
    cols = len(arr[0]) if rows > 0 else 0

    for r in range(rows):
        for c in range(cols):
            if arr[r][c] == target_id:
                coords.append((r, c))
    return coords

def calculate_min_manhattan_distance(arr, id1, id2):
    coords1 = get_coords_for_id(arr, id1)
    coords2 = get_coords_for_id(arr, id2)

    if not coords1 or not coords2:
        return float('inf')

    min_dist = float('inf')

    for r1, c1 in coords1:
        for r2, c2 in coords2:
            dist = abs(r1 - r2) + abs(c1 - c2)
            if dist < min_dist:
                min_dist = dist

    return min_dist

def compute_pairwise_distances(arr):
    unique_ids = get_unique_ids(arr)
    n = len(unique_ids)

    # Initialize result list to store tuples (from_id, to_id, distance)
    results = []

    for i in range(n):
        id1 = unique_ids[i]
        for j in range(n):
            id2 = unique_ids[j]
            if i == j:
                dist = 0
            else:
                dist = calculate_min_manhattan_distance(arr, id1, id2)
            results.append((id1, id2, dist))

    return results

