import csv
import io

def manual_one_hot_encode(data_rows, list_column_index):
    """
    Manually one-hot encodes a specific column containing lists of elements.

    Args:
        data_rows (list of lists): The raw data rows including headers.
        list_column_index (int): The index of the column containing the lists to encode.

    Returns:
        list of lists: The new data structure with one-hot encoded columns added.
    """
    if not data_rows:
        return []

    # Extract header and data
    original_header = data_rows[0]
    original_data = data_rows[1:]

    # Step 1: Find all unique elements across the target column manually
    unique_elements = []

    for row in original_data:
        if list_column_index >= len(row):
            continue

        cell_value = row[list_column_index]

        # Handle cases where the cell might be a string representation of a list or an actual list
        # Assuming input is already parsed lists based on the prompt description, 
        # but we add a safety check for string parsing if needed.
        if isinstance(cell_value, str):
            # Simple manual parsing for "[A, B]" format if passed as string
            cell_value = []
            clean_str = cell_value.replace('[', '').replace(']', '')
            if clean_str:
                parts = clean_str.split(',')
                for part in parts:
                    cleaned_part = part.strip().strip('"').strip("'")
                    if cleaned_part:
                        cell_value.append(cleaned_part)

        # Iterate through the list in the current row
        if isinstance(cell_value, list):
            for item in cell_value:
                is_new = True
                for existing in unique_elements:
                    if item == existing:
                        is_new = False
                        break
                if is_new:
                    unique_elements.append(item)

    # Step 2: Create the new header
    new_header = list(original_header)
    for element in unique_elements:
        new_header.append(element)

    # Step 3: Construct the new data rows
    final_data = [new_header]

    for row in original_data:
        new_row = list(row)

        # Get the list of items for this specific row
        current_items = []
        if list_column_index < len(row):
            cell_value = row[list_column_index]
            if isinstance(cell_value, str):
                clean_str = cell_value.replace('[', '').replace(']', '')
                if clean_str:
                    parts = clean_str.split(',')
                    for part in parts:
                        cleaned_part = part.strip().strip('"').strip("'")
                        if cleaned_part:
                            current_items.append(cleaned_part)
            elif isinstance(cell_value, list):
                current_items = cell_value

        # Generate 0s and 1s for each unique element
        for element in unique_elements:
            exists = False
            for item in current_items:
                if item == element:
                    exists = True
                    break

            if exists:
                new_row.append(1)
            else:
                new_row.append(0)

        final_data.append(new_row)

    return final_data

