import math
import random

def sigmoid(z):
    if z >= 0:
        return 1.0 / (1.0 + math.exp(-z))
    else:
        exp_z = math.exp(z)
        return exp_z / (1.0 + exp_z)

def dot_product(v1, v2):
    result = 0.0
    for i in range(len(v1)):
        result += v1[i] * v2[i]
    return result

def add_bias_feature(x_row):
    new_row = [1.0]
    for val in x_row:
        new_row.append(val)
    return new_row

def prepare_data_with_bias(X, y):
    X_new = []
    for row in X:
        X_new.append(add_bias_feature(row))
    return X_new, y

def train_logistic_regression(X, y, learning_rate=0.1, iterations=1000):
    n_samples = len(X)
    n_features = len(X[0])

    weights = [0.0] * n_features

    for _ in range(iterations):
        gradients = [0.0] * n_features

        for i in range(n_samples):
            z = dot_product(X[i], weights)
            prediction = sigmoid(z)
            error = prediction - y[i]

            for j in range(n_features):
                gradients[j] += error * X[i][j]

        for j in range(n_features):
            weights[j] -= learning_rate * (gradients[j] / n_samples)

    return weights

def predict_proba_single(X, weights):
    probabilities = []
    for row in X:
        z = dot_product(row, weights)
        prob = sigmoid(z)
        probabilities.append(prob)
    return probabilities

def create_folds(data_X, data_y, n_folds):
    n_samples = len(data_X)
    fold_size = n_samples // n_folds
    folds_X = []
    folds_y = []

    for i in range(n_folds):
        start_idx = i * fold_size
        if i == n_folds - 1:
            end_idx = n_samples
        else:
            end_idx = (i + 1) * fold_size

        current_fold_X = []
        current_fold_y = []

        for j in range(start_idx, end_idx):
            current_fold_X.append(data_X[j])
            current_fold_y.append(data_y[j])

        folds_X.append(current_fold_X)
        folds_y.append(current_fold_y)

    return folds_X, folds_y

def cross_validate_logistic_regression(X, y, n_folds=5):
    X_bias, y = prepare_data_with_bias(X, y)
    folds_X, folds_y = create_folds(X_bias, y, n_folds)

    all_predictions = [0.0] * len(y)

    for i in range(n_folds):
        test_fold_X = folds_X[i]
        test_fold_y = folds_y[i]

        train_X = []
        train_y = []

        for j in range(n_folds):
            if j != i:
                for k in range(len(folds_X[j])):
                    train_X.append(folds_X[j][k])
                    train_y.append(folds_y[j][k])

        weights = train_logistic_regression(train_X, train_y)

        fold_predictions = predict_proba_single(test_fold_X, weights)

        start_idx = 0
        for j in range(n_folds):
            if j < i:
                start_idx += len(folds_y[j])

        for k in range(len(test_fold_y)):
            all_predictions[start_idx + k] = fold_predictions[k]

    return all_predictions

