class CrossValidationVisualizer:
    def __init__(self):
        self.results = []

    def get_model_name(self, model):
        if hasattr(model, 'name'):
            return model.name
        if hasattr(model, '_get_tags'):
            tags = model._get_tags()
            if 'name' in tags:
                return tags['name']
        if hasattr(model, 'estimator_type'):
            return type(model).__name__
        return type(model).__name__

    def calculate_mean(self, scores_list):
        total = 0.0
        count = 0
        for score in scores_list:
            total = total + float(score)
            count = count + 1
        if count == 0:
            return 0.0
        return total / float(count)

    def run_cross_validation(self, models, X, y, cv_folds=5):
        for model in models:
            model_name = self.get_model_name(model)
            scores_list = []

            for fold_index in range(cv_folds):
                current_fold_scores = []

                for sample_index in range(len(y)):
                    is_train = 1
                    if fold_index == (sample_index % cv_folds):
                        is_train = 0

                    if is_train == 1:
                        train_indices_list = []
                        test_indices_list = []

                        for idx in range(len(y)):
                            if idx != sample_index:
                                train_indices_list.append(idx)
                            else:
                                test_indices_list.append(idx)

                        X_train_fold = []
                        y_train_fold = []
                        X_test_fold = []
                        y_test_fold = []

                        for idx in train_indices_list:
                            X_train_fold.append(X[idx])
                            y_train_fold.append(y[idx])

                        for idx in test_indices_list:
                            X_test_fold.append(X[idx])
                            y_test_fold.append(y[idx])

                        model_copy = None
                        if hasattr(model, 'clone'):
                            model_copy = model.clone()
                        else:
                            model_copy = model

                        try:
                            model_copy.fit(X_train_fold, y_train_fold)
                            predictions = []
                            for test_sample in X_test_fold:
                                pred = model_copy.predict(test_sample)
                                if isinstance(pred, list):
                                    predictions.append(pred[0])
                                else:
                                    predictions.append(pred)

                            fold_score = 0.0
                            count_preds = 0
                            for i in range(len(predictions)):
                                true_val = y_test_fold[i]
                                pred_val = predictions[i]

                                if isinstance(true_val, (list, tuple)):
                                    true_val = true_val[0]
                                if isinstance(pred_val, (list, tuple)):
                                    pred_val = pred_val[0]

                                if isinstance(true_val, float) and isinstance(pred_val, float):
                                    diff = abs(true_val - pred_val)
                                    fold_score = fold_score + diff
                                    count_preds = count_preds + 1

                                elif isinstance(true_val, int) and isinstance(pred_val, int):
                                    diff = abs(true_val - pred_val)
                                    fold_score = fold_score + diff
                                    count_preds = count_preds + 1

                                elif isinstance(true_val, str) and isinstance(pred_val, str):
                                    if true_val == pred_val:
                                        fold_score = fold_score + 1.0
                                    else:
                                        fold_score = fold_score + 0.0
                                    count_preds = count_preds + 1

                                elif isinstance(true_val, (list, tuple)) and isinstance(pred_val, (list, tuple)):
                                    if len(true_val) == len(pred_val):
                                        for t_v, p_v in zip(true_val, pred_val):
                                            if isinstance(t_v, float) and isinstance(p_v, float):
                                                diff = abs(t_v - p_v)
                                                fold_score = fold_score + diff
                                            elif isinstance(t_v, int) and isinstance(p_v, int):
                                                diff = abs(t_v - p_v)
                                                fold_score = fold_score + diff
                                            elif isinstance(t_v, str) and isinstance(p_v, str):
                                                if t_v == p_v:
                                                    fold_score = fold_score + 1.0
                                                else:
                                                    fold_score = fold_score + 0.0
                                        count_preds = count_preds + 1

                                else:
                                    try:
                                        true_float = float(true_val)
                                        pred_float = float(pred_val)
                                        diff = abs(true_float - pred_float)
                                        fold_score = fold_score + diff
                                        count_preds = count_preds + 1
                                    except (ValueError, TypeError):
                                        pass

                        except Exception:
                            fold_score = 0.0
                        finally:
                            if model_copy is not None and hasattr(model_copy, 'memory'):
                                del model_copy.memory
                            elif model_copy is not None:
                                pass
                        scores_list.append(fold_score)

                    else:
                        continue

            mean_score = self.calculate_mean(scores_list)
            self.results.append({'Model Name': model_name, 'Mean Score': mean_score})

    def print_results(self):
        for result in self.results:
            print("Name Model: " + str(result['Model Name']) + ", Mean Score: " + str(result['Mean Score']))

def main():
    # Simulating data since no external libraries are allowed
    X_data = []
