import math

def manual_mean(values):
    total = 0.0
    count = 0
    for val in values:
        total = total + val
        count = count + 1
    if count == 0:
        return 0.0
    return total / float(count)

def manual_cross_val_score(model, X, y, cv):
    n_samples = len(X)
    fold_size = n_samples // cv

    scores = []

    for i in range(cv):
        start_idx = i * fold_size

        if i == cv - 1:
            end_idx = n_samples
        else:
            end_idx = (i + 1) * fold_size

        X_test = []
        y_test = []
        X_train = []
        y_train = []

        for j in range(n_samples):
            if start_idx <= j < end_idx:
                X_test.append(X[j])
                y_test.append(y[j])
            else:
                X_train.append(X[j])
                y_train.append(y[j])

        model.fit(X_train, y_train)
        predictions = model.predict(X_test)

        correct_count = 0
        for k in range(len(predictions)):
            if predictions[k] == y_test[k]:
                correct_count = correct_count + 1

        accuracy = float(correct_count) / float(len(predictions))
        scores.append(accuracy)

    return scores

def get_model_name(model):
    model_str = str(model)

    if '(' in model_str:
        name_part = model_str.split('(')[0]
        return name_part.strip()
    else:
        return model_str.strip()

class LinearRegression:
    def __init__(self, copy_X=True, fit_intercept=True, n_jobs=1, normalize=False):
        self.copy_X = copy_X
        self.fit_intercept = fit_intercept
        self.n_jobs = n_jobs
        self.normalize = normalize
        self.coef_ = None
        self.intercept_ = 0.0

    def fit(self, X, y):
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        sum_x = [0.0] * n_features
        sum_y = 0.0
        sum_xy = [0.0] * n_features
        sum_xx = [0.0] * n_features

        for i in range(n_samples):
            y_val = y[i]
            sum_y = sum_y + y_val
            for j in range(n_features):
                x_val = X[i][j]
                sum_x[j] = sum_x[j] + x_val
                sum_xy[j] = sum_xy[j] + (x_val * y_val)
                sum_xx[j] = sum_xx[j] + (x_val * x_val)

        mean_x = [0.0] * n_features
        mean_y = 0.0

        if n_samples > 0:
            for j in range(n_features):
                mean_x[j] = sum_x[j] / float(n_samples)
            mean_y = sum_y / float(n_samples)

        self.coef_ = [0.0] * n_features
        for j in range(n_features):
            numerator = sum_xy[j] - (sum_x[j] * mean_y)
            denominator = sum_xx[j] - (sum_x[j] * mean_x[j])
            if denominator != 0:
                self.coef_[j] = numerator / denominator
            else:
                self.coef_[j] = 0.0

        self.intercept_ = mean_y
        for j in range(n_features):
            self.intercept_ = self.intercept_ - (self.coef_[j] * mean_x[j])

    def predict(self, X):
        predictions = []
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        for i in range(n_samples):
            pred_val = self.intercept_
            for j in range(n_features):
                pred_val = pred_val + (self.coef_[j] * X[i][j])
            predictions.append(pred_val)

        return predictions

class LogisticRegression:
    def __init__(self, penalty='l2', C=1.0, solver='lbfgs', max_iter=100):
        self.penalty = penalty
        self.C = C
        self.solver = solver
        self.max_iter = max_iter
        self.coef_ = None
        self.intercept_ = 0.0

    def _sigmoid(self, z):
        if z > 500:
            return 1.0
        if z < -500:
            return 0.0
        return 1.0 / (1.0 + math.exp(-z))

    def fit(self, X, y):
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        self.coef_ = [0.0] * n_features
        self.intercept_ = 0.0

        learning_rate = 0.1

        for iteration in range(self.max_iter):
            grad_coef = [0.0] * n_features
            grad_intercept = 0.0

            for i in range(n_samples):
                z = self.intercept_
                for j in range(n_features):
                    z = z + (self.coef_[j] * X[i][j])

                pred = self._sigmoid(z)
                error = pred - y[i]

                grad_intercept = grad_intercept + error
                for j in range(n_features):
                    grad_coef[j] = grad_coef[j] + (error * X[i][j])

            for j in range(n_features):
                self.coef_[j] = self.coef_[j] - (learning_rate * grad_coef[j] / float(n_samples))
            self.intercept_ = self.intercept_ - (learning_rate * grad_intercept / float(n_samples))

    def predict(self, X):
        predictions = []
        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        for i in range(n_samples):
            z = self.intercept_
            for j in range(n_features):
                z = z + (self.coef_[j] * X[i][j])

            pred_prob = self._sigmoid(z)
            if pred_prob >= 0.5:
                predictions.append(1)
            else:
                predictions.append(0)

        return predictions

class DecisionTreeClassifier:
    def __init__(self, criterion='gini', max_depth=None):
        self.criterion = criterion
        self.max_depth = max_depth
        self.tree = None

    def _gini(self, y_list):
        if len(y_list) == 0:
            return 0.0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        p0 = float(count_0) / float(len(y_list))
        p1 = float(count_1) / float(len(y_list))

        return 1.0 - (p0 * p0) - (p1 * p1)

    def _entropy(self, y_list):
        if len(y_list) == 0:
            return 0.0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        p0 = float(count_0) / float(len(y_list))
        p1 = float(count_1) / float(len(y_list))

        if p0 == 0.0 and p1 == 0.0:
            return 0.0

        result = 0.0
        if p0 > 0.0:
            result = result - (p0 * math.log2(p0))
        if p1 > 0.0:
            result = result - (p1 * math.log2(p1))

        return result

    def _information_gain(self, y_parent, y_left, y_right):
        impurity_func = self._gini if self.criterion == 'gini' else self._entropy

        parent_impurity = impurity_func(y_parent)

        n_total = len(y_parent)
        n_left = len(y_left)
        n_right = len(y_right)

        if n_total == 0:
            return 0.0

        left_weight = float(n_left) / float(n_total)
        right_weight = float(n_right) / float(n_total)

        child_impurity = (left_weight * impurity_func(y_left)) + (right_weight * impurity_func(y_right))

        return parent_impurity - child_impurity

    def _build_tree(self, X, y, depth):
        if self.max_depth is not None and depth >= self.max_depth:
            return {'leaf': True, 'value': self._majority_vote(y)}

        if len(set(y)) == 1 or len(y) <= 1:
            return {'leaf': True, 'value': self._majority_vote(y)}

        n_samples = len(X)
        n_features = len(X[0]) if n_samples > 0 else 0

        best_gain = -1.0
        best_feature = -1
        best_threshold = 0.0

        for feature_idx in range(n_features):
            values = []
            for i in range(n_samples):
                values.append(X[i][feature_idx])

            min_val = values[0]
            max_val = values[0]
            for val in values:
                if val < min_val:
                    min_val = val
                if val > max_val:
                    max_val = val

            step = (max_val - min_val) / 10.0 if max_val != min_val else 1.0

            for threshold in range(int(min_val), int(max_val) + 1):
                y_left = []
                y_right = []

                for i in range(n_samples):
                    if X[i][feature_idx] <= threshold:
                        y_left.append(y[i])
                    else:
                        y_right.append(y[i])

                if len(y_left) == 0 or len(y_right) == 0:
                    continue

                gain = self._information_gain(y, y_left, y_right)

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = float(threshold)

        if best_feature == -1:
            return {'leaf': True, 'value': self._majority_vote(y)}

        X_left = []
        y_left = []
        X_right = []
        y_right = []

        for i in range(n_samples):
            if X[i][best_feature] <= best_threshold:
                X_left.append(X[i])
                y_left.append(y[i])
            else:
                X_right.append(X[i])
                y_right.append(y[i])

        left_tree = self._build_tree(X_left, y_left, depth + 1)
        right_tree = self._build_tree(X_right, y_right, depth + 1)

        return {
            'leaf': False,
            'feature': best_feature,
            'threshold': best_threshold,
            'left': left_tree,
            'right': right_tree
        }

    def _majority_vote(self, y_list):
        if len(y_list) == 0:
            return 0

        count_0 = 0
        count_1 = 0

        for val in y_list:
            if val == 0:
                count_0 = count_0 + 1
            else:
                count_1 = count_1 + 1

        return 1 if count_1 > count_0 else 0

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, 0)

    def _predict_single(self, x, node):
        if node['leaf']:
            return node['value']

        if x[node['feature']] <= node['threshold']:
            return self._predict_single(x, node['left'])
        else:
            return self._predict_single(x, node['right'])

    def predict(self, X):
        predictions = []
        for i in range(len(X)):
            pred = self._predict_single(X[i], self.tree)
            predictions.append(pred)
        return predictions

def main():
    X = [
        [1.0, 2.0], [2.0, 3.0], [3.0, 4.0], [4.0, 5.0], [5.0, 6.0],
