class CrossValidationVisualizer:
    def __init__(self):
        self.results = []

    def get_model_name(self, model):
        if hasattr(model, 'name'):
            return model.name
        elif hasattr(model, '_estimator_type'):
            return type(model).__name__
        else:
            return type(model).__name__

    def run_cross_validation(self, models, X, y, cv=5):
        for model in models:
            scores = []
            for i in range(cv):
                indices = self._create_indices(len(y), cv)
                train_idx = indices[i]
                test_idx = [j for j in range(len(y)) if j not in train_idx]

                X_train = [X[j] for j in train_idx]
                y_train = [y[j] for j in train_idx]
                X_test = [X[j] for j in test_idx]
                y_test = [y[j] for j in test_idx]

                model_copy = self._deepcopy_model(model)
                model_copy.fit(X_train, y_train)
                pred = model_copy.predict(X_test)
                correct = 0
                total = len(pred)
                for k in range(total):
                    if pred[k] == y_test[k]:
                        correct += 1

                score = float(correct) / float(total)
                scores.append(score)

            mean_score = self._calculate_mean(scores)
            model_name = self.get_model_name(model)
            self.results.append({
                'Model Name': model_name,
                'Mean Score': mean_score
            })

    def _create_indices(self, total_samples, n_folds):
        indices = []
        for i in range(total_samples):
            indices.append(i)

        fold_size = total_samples // n_folds
        remainder = total_samples % n_folds

        current_idx = 0
        folds = []

        for f in range(n_folds):
            if f < remainder:
                fold_size += 1

            start = current_idx
            end = start + fold_size
            fold_indices = []
            for idx in range(start, end):
                if idx < total_samples:
                    fold_indices.append(idx)

            folds.append(fold_indices)
            current_idx = end

        return folds

    def _calculate_mean(self, values):
        total = 0.0
        count = 0
        for val in values:
            total += val
            count += 1

        if count == 0:
            return 0.0
        return total / float(count)

    def _deepcopy_model(self, model):
        new_model = type(model)()
        attributes = self._get_attributes(model)
        for attr_name in attributes:
            attr_value = getattr(model, attr_name)
            setattr(new_model, attr_name, attr_value)
        return new_model

    def _get_attributes(self, obj):
        attributes = []
        for key in dir(obj):
            if not key.startswith('_'):
                try:
                    value = getattr(obj, key)
                    if not callable(value):
                        attributes.append(key)
                except:
                    pass
        return attributes

    def print_results(self):
        for result in self.results:
            print(f"Name Model: {result['Model Name']}, Mean Score: {result['Mean Score']}")

