# The input data in the example is transposed (T), so columns are sentences.
# Original: rows=1, cols=3. Transposed: rows=3, cols=1.
# So we create 3 rows, each containing 1 sentence.
data_rows = []
for i in range(len(raw_text_list)):
    row_data = [raw_text_list[i]]
    data_rows.append(row_data)

# We need a simple class to mimic the DataFrame behavior for column access without using pandas
class SimpleDataFrame:
    def __init__(self, rows, columns):
        self._data = rows
        self._columns = columns

    def __getitem__(self, key):
        if isinstance(key, str):
            col_index = -1
            for idx, col_name in enumerate(self._columns):
                if col_name == key:
                    col_index = idx
                    break
            if col_index == -1:
                raise KeyError(f"Column {key} not found")

            # Extract the column as a list of strings
            result_list = []
            for row in self._data:
                if col_index < len(row):
                    result_list.append(row[col_index])
                else:
                    result_list.append("")
            return SimpleDataFrame([result_list], [key])
        elif isinstance(key, slice):
            # Handle slicing of rows
            start = key.start if key.start is not None else 0
            stop = key.stop if key.stop is not None else len(self._data)
            step = key.step if key.step is not None else 1

            sliced_rows = []
            for i in range(start, stop, step):
                if i < len(self._data):
                    sliced_rows.append(self._data[i])
            return SimpleDataFrame(sliced_rows, self._columns)
        else:
            raise TypeError("Key must be a string or slice")

# Create the DataFrame object
df = SimpleDataFrame(data_rows, ["test"])

# Define a manual TfidfVectorizer class from scratch
class ManualTfidfVectorizer:
    def __init__(self):
        self.vocabulary_ = {}
        self.idf_ = {}
        self._idf_sum = {}

    def _tokenize(self, text):
        # Simple tokenization: lowercase and split by whitespace
        text_lower = text.lower()
        tokens = []
        current_token = ""
        for char in text_lower:
            if char.isalnum():
                current_token += char
            else:
                if current_token:
                    tokens.append(current_token)
                    current_token = ""
        if current_token:
            tokens.append(current_token)
        return tokens

    def fit(self, documents):
        # Count document frequency for each term
        doc_freq = {}
        all_terms = set()

        for doc in documents:
            tokens = self._tokenize(doc)
            unique_tokens_in_doc = set(tokens)

            for token in unique_tokens_in_doc:
                if token not in doc_freq:
                    doc_freq[token] = 0
                doc_freq[token] += 1
                all_terms.add(token)

        # Calculate IDF and total document count
        n_docs = len(documents)

        for term in all_terms:
            df_val = doc_freq[term]
            self._idf_sum[term] = df_val
            # IDF formula: log(N / df) + 1 (smoothed) or just log(N/df)
            # Using standard log(N/df)
            idf_val = 0.0
            if n_docs > 0 and df_val > 0:
                import math
                idf_val = math.log(n_docs / df_val)
            self.idf_[term] = idf_val

        # Build vocabulary mapping term -> index
        idx = 0
        for term in sorted(all_terms):
            self.vocabulary_[term] = idx
            idx += 1

    def transform(self, documents):
        n_docs = len(documents)
        n_features = len(self.vocabulary_)

        # Initialize matrix with zeros
        matrix = []
        for _ in range(n_docs):
            row = [0.0] * n_features
            matrix.append(row)

        for doc_idx, doc in enumerate(documents):
            tokens = self._tokenize(doc)

            # Count term frequency in this document
            term_freq = {}
            for token in tokens:
                if token in term_freq:
                    term_freq[token] += 1
                else:
                    term_freq[token] = 1

            # Calculate TF-IDF values
            for term, tf_val in term_freq.items():
                if term in self.vocabulary_:
                    feature_idx = self.vocabulary_[term]
                    idf_val = self.idf_.get(term, 0.0)
                    matrix[doc_idx][feature_idx] = tf_val * idf_val

        return matrix

    def fit_transform(self, documents):
        self.fit(documents)
        return self.transform(documents)

