import sys
import re
import math
from collections import defaultdict

# Manual implementation of TfidfVectorizer without sklearn or numpy
class ManualTfidfVectorizer:
    def __init__(self, lowercase=True):
        self.lowercase = lowercase
        self.vocabulary_ = {}
        self.idf_ = {}
        self.feature_names_ = []

    def _tokenize(self, text):
        if self.lowercase:
            text = text.lower()
        # Simple tokenization: split by non-alphanumeric characters
        tokens = re.findall(r'\b\w+\b', text)
        return tokens

    def fit(self, documents):
        doc_count = len(documents)
        term_doc_freq = defaultdict(int)

        # Count document frequency for each term
        for doc in documents:
            tokens = self._tokenize(doc)
            unique_tokens = set(tokens)
            for token in unique_tokens:
                term_doc_freq[token] += 1

        # Build vocabulary and IDF
        sorted_terms = []
        for term in term_doc_freq:
            sorted_terms.append(term)

        # Manual sorting (bubble sort) to ensure deterministic order
        n = len(sorted_terms)
        for i in range(n):
            for j in range(0, n - i - 1):
                if sorted_terms[j] > sorted_terms[j + 1]:
                    temp = sorted_terms[j]
                    sorted_terms[j] = sorted_terms[j + 1]
                    sorted_terms[j + 1] = temp

        self.vocabulary_ = {}
        for idx, term in enumerate(sorted_terms):
            self.vocabulary_[term] = idx
            # IDF calculation: log(N / (df + 1)) + 1 (smoothed)
            df = term_doc_freq[term]
            idf_val = math.log(doc_count / (df + 1)) + 1.0
            self.idf_[term] = idf_val

        self.feature_names_ = sorted_terms
        return self

    def transform(self, documents):
        # Initialize result matrix manually
        n_docs = len(documents)
        n_features = len(self.vocabulary_)

        # Create a list of lists for the matrix
        matrix = []
        for _ in range(n_docs):
            row = [0.0] * n_features
            matrix.append(row)

        for doc_idx, doc in enumerate(documents):
            tokens = self._tokenize(doc)

            # Count term frequencies in this document
            tf_counts = defaultdict(int)
            for token in tokens:
                if token in self.vocabulary_:
                    tf_counts[token] += 1

            # Calculate TF-IDF scores
            doc_norm = 0.0
            temp_row = [0.0] * n_features

            for term, count in tf_counts.items():
                idx = self.vocabulary_[term]
                tf_val = count / len(tokens) if len(tokens) > 0 else 0.0
                idf_val = self.idf_.get(term, 0.0)
                score = tf_val * idf_val
                temp_row[idx] = score
                doc_norm += score ** 2

            # L2 normalization
            if doc_norm > 0:
                norm_factor = math.sqrt(doc_norm)
                for i in range(n_features):
                    matrix[doc_idx][i] = temp_row[i] / norm_factor
            else:
                matrix[doc_idx] = temp_row

        return matrix

    def fit_transform(self, documents):
        self.fit(documents)
        return self.transform(documents)

# Manual implementation of NMF (Non-negative Matrix Factorization) using multiplicative update rules
class ManualNMF:
    def __init__(self, n_components=2, max_iter=100, tol=1e-4):
        self.n_components = n_components
        self.max_iter = max_iter
        self.tol = tol

    def _initialize(self, V, n_samples, n_features):
        # Initialize W and H with small random values (using deterministic pseudo-random)
        # Using simple counter-based initialization for reproducibility without numpy
        import random
        random.seed(42)

        W = []
        for i in range(n_samples):
            row = [random.random() * 0.1 + 0.01 for _ in range(self.n_components)]
            W.append(row)

        H = []
        for j in range(self.n_components):
            row = [random.random() * 0.1 + 0.01 for _ in range(n_features)]
            H.append(row)

        return W, H

    def _matrix_multiply(self, A, B):
        # Multiply matrix A (m x k) and B (k x n) -> result (m x n)
        m = len(A)
        k = len(A[0]) if m > 0 else 0
        n = len(B[0]) if len(B) > 0 else 0

        result = []
        for i in range(m):
            row = [0.0] * n
            for j in range(n):
                val = 0.0
                for l in range(k):
                    val += A[i][l] * B[l][j]
                row[j] = val
            result.append(row)
        return result

    def _matrix_transpose(self, A):
        m = len(A)
        n = len(A[0]) if m > 0 else 0
        result = []
        for j in range(n):
            row = [A[i][j] for i in range(m)]
            result.append(row)
        return result

    def _reconstruct_error(self, V, W, H):
        # Calculate Frobenius norm of (V - WH)
        WH = self._matrix_multiply(W, H)
        error_sum = 0.0

        for i in range(len(V)):
            for j in range(len(V[0])):
                diff = V[i][j] - WH[i][j]
                error_sum += diff * diff

        return math.sqrt(error_sum)

    def fit(self, V):
        n_samples = len(V)
        n_features = len(V[0]) if n_samples > 0 else 0

        W, H = self._initialize(V, n_samples, n_features)

        prev_error = float('inf')

        for iteration in range(self.max_iter):
            # Update H: H = H * (W^T V) / (W^T W H + epsilon)
            W_T = self._matrix_transpose(W)
            W_T_V = self._matrix_multiply(W_T, V)
            W_T_W = self._matrix_multiply(W_T, W)
            W_T_W_H = self._matrix_multiply(W_T_W, H)

            for j in range(self.n_components):
                for k in range(n_features):
                    numerator = W_T_V[j][k]
                    denominator = W_T_W_H[j][k] + 1e-10
                    H[j][k] = H[j][k] * (numerator / denominator)

            # Update W: W = W * (V H^T) / (W H H^T + epsilon)
            H_T = self._matrix_transpose(H)
            V_H_T = self._matrix_multiply(V, H_T)
            H_H_T = self._matrix_multiply(H, H_T)
            W_H_H_T = self._matrix_multiply(W, H_H_T)

            for i in range(n_samples):
                for j in range(self.n_components):
                    numerator = V_H_T[i][j]
                    denominator = W_H_H_T[i][j] + 1e-10
                    W[i][j] = W[i][j] * (numerator / denominator)

            # Check convergence
            current_error = self._reconstruct_error(V, W, H)
            if abs(prev_error - current_error) < self.tol:
                break
            prev_error = current_error

        self.W_ = W
        self.H_ = H
        return self

    def transform(self, V):
        # For NMF, transform usually returns the W matrix (latent features)
        return self.W_

    def fit_transform(self, V):
        self.fit(V)
        return self.transform(V)

# Manual Pipeline implementation
class ManualPipeline:
    def __init__(self, steps):
        self.steps = steps
        self.named_steps = {}
        for name, transformer in steps:
            self.named_steps[name] = transformer

    def fit_transform(self, X):
        current_data = X

        # Store intermediate results
        intermediate_results = {}

        for name, transformer in self.steps:
            if hasattr(transformer, 'fit_transform'):
                current_data = transformer.fit_transform(current_data)
            elif hasattr(transformer, 'fit') and hasattr(transformer, 'transform'):
                transformer.fit(current_data)
                current_data = transformer.transform(current_data)

            intermediate_results[name] = current_data

        self.intermediate_results_ = intermediate_results
        return current_data

    def get_intermediate_result(self, step_name):
        if not hasattr(self, 'intermediate_results_'):
            raise ValueError("Pipeline has not been fitted yet.")

        if step_name not in self.intermediate_results_:
            raise ValueError(f"Step '{step_name}' not found in pipeline or no intermediate result available.")

        return self.intermediate_results_[step_name]

# Main execution code
def main():
    # Sample data
    data = [
        "Salut comment tu vas",
        "Hey how are you today",
        "I am okay and you ?"
    ]

    # Create pipeline with manual implementations
    pipe = ManualPipeline([
        ("tf_idf", ManualTfidfVectorizer()),
        ("nmf", ManualNMF(n_components=2))
    ])

    # Fit and transform
    final_result = pipe.fit_transform(data)

    # Get intermediate result (TF-IDF output)
    tfidf_output = pipe.get_intermediate_result("tf_idf")

    print("Intermediate TF-IDF Output:")
    for i, row in enumerate(tfidf_output):
        print(f"Document {i}: {row}")

    print("\nFinal NMF Result (W matrix):")
    for i, row in enumerate(final_result):
        print(f"Document {i}: {row}")

