import math
import random

class DecisionTreeRegressor:
    def __init__(self, max_depth=None, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.tree = None

    def fit(self, X, y):
        # Ensure X is a list of lists (samples x features)
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        self.tree = self._build_tree(X, y, 0)

    def _build_tree(self, X, y, depth):
        n_samples = len(y)

        # Stopping conditions
        if (self.max_depth is not None and depth >= self.max_depth) or \
           n_samples < self.min_samples_split or \
           n_samples == 0:
            return self._calculate_mean(y)

        # Find best split
        best_feature, best_threshold, best_gain = self._find_best_split(X, y)

        if best_gain <= 0:
            return self._calculate_mean(y)

        # Split data
        left_indices = []
        right_indices = []

        for i in range(n_samples):
            if X[i][best_feature] <= best_threshold:
                left_indices.append(i)
            else:
                right_indices.append(i)

        if len(left_indices) == 0 or len(right_indices) == 0:
            return self._calculate_mean(y)

        # Create left and right subsets
        X_left = [X[i] for i in left_indices]
        y_left = [y[i] for i in left_indices]
        X_right = [X[i] for i in right_indices]
        y_right = [y[i] for i in right_indices]

        # Recursively build subtrees
        return {
            'feature': best_feature,
            'threshold': best_threshold,
            'left': self._build_tree(X_left, y_left, depth + 1),
            'right': self._build_tree(X_right, y_right, depth + 1)
        }

    def _find_best_split(self, X, y):
        n_samples = len(y)
        n_features = len(X[0])
        best_gain = -float('inf')
        best_feature = None
        best_threshold = None

        # Calculate total variance (MSE) before split
        mean_y = self._calculate_mean(y)
        total_var = 0.0
        for val in y:
            total_var += (val - mean_y) ** 2

        for feature_idx in range(n_features):
            # Get unique values for this feature to use as potential thresholds
            feature_values = [X[i][feature_idx] for i in range(n_samples)]

            # Sort manually without using sorted()
            sorted_indices = list(range(n_samples))
            for i in range(len(sorted_indices)):
                for j in range(i + 1, len(sorted_indices)):
                    if feature_values[sorted_indices[i]] > feature_values[sorted_indices[j]]:
                        temp = sorted_indices[i]
                        sorted_indices[i] = sorted_indices[j]
                        sorted_indices[j] = temp

            # Try splitting between consecutive unique values
            for i in range(len(sorted_indices) - 1):
                idx1 = sorted_indices[i]
                idx2 = sorted_indices[i + 1]

                if feature_values[idx1] == feature_values[idx2]:
                    continue

                threshold = (feature_values[idx1] + feature_values[idx2]) / 2.0

                # Split data based on this threshold
                left_y = []
                right_y = []

                for k in range(n_samples):
                    if X[k][feature_idx] <= threshold:
                        left_y.append(y[k])
                    else:
                        right_y.append(y[k])

                if len(left_y) == 0 or len(right_y) == 0:
                    continue

                # Calculate variance reduction (gain)
                mean_left = self._calculate_mean(left_y)
                mean_right = self._calculate_mean(right_y)

                var_left = 0.0
                for val in left_y:
                    var_left += (val - mean_left) ** 2

                var_right = 0.0
                for val in right_y:
                    var_right += (val - mean_right) ** 2

                # Weighted variance after split
                weighted_var = (len(left_y) * var_left + len(right_y) * var_right) / n_samples

                gain = total_var - weighted_var

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    def _calculate_mean(self, y):
        if len(y) == 0:
            return 0.0

        total = 0.0
        for val in y:
            total += val

        return total / len(y)

    def predict(self, X):
        # Ensure X is a list of lists
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        predictions = []
        for sample in X:
            pred = self._predict_single(sample, self.tree)
            predictions.append(pred)

        return predictions

    def _predict_single(self, sample, node):
        if isinstance(node, (int, float)):
            return node

        if sample[node['feature']] <= node['threshold']:
            return self._predict_single(sample, node['left'])
        else:
            return self._predict_single(sample, node['right'])


class RandomForestRegressor:
    def __init__(self, n_estimators=100, max_depth=None, min_samples_split=2, random_state=None):
        self.n_estimators = n_estimators
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.random_state = random_state
        self.trees = []

    def fit(self, X, y):
        # Ensure X is a list of lists (samples x features)
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        n_samples = len(y)

        if self.random_state is not None:
            random.seed(self.random_state)

        self.trees = []

        for _ in range(self.n_estimators):
            # Bootstrap sampling (random sampling with replacement)
            indices = []
            for _ in range(n_samples):
                idx = random.randint(0, n_samples - 1)
                indices.append(idx)

            X_bootstrap = [X[i] for i in indices]
            y_bootstrap = [y[i] for i in indices]

            # Train a decision tree on bootstrap sample
            tree = DecisionTreeRegressor(
                max_depth=self.max_depth,
                min_samples_split=self.min_samples_split
            )
            tree.fit(X_bootstrap, y_bootstrap)
            self.trees.append(tree)

    def predict(self, X):
        # Ensure X is a list of lists
        if not isinstance(X[0], list):
            X = [[x] for x in X]

        all_predictions = []

        # Get predictions from each tree
        for tree in self.trees:
            tree_preds = tree.predict(X)
            all_predictions.append(tree_preds)

        # Average predictions across all trees
        n_samples = len(X)
        final_predictions = []

        for i in range(n_samples):
            total = 0.0
            for tree_idx in range(len(self.trees)):
                total += all_predictions[tree_idx][i]

            avg = total / len(self.trees)
            final_predictions.append(avg)

        return final_predictions


# Example usage with the provided data format
if __name__ == "__main__":
    # Sample data (truncated for demonstration)
    X_data = [
        735233.27082176, 735234.27082176, 735235.27082176, 735236.27082176,
        735237.27082176, 735238.27082176, 735239.27082176, 735240.27082176,
        735241.27082176, 735242.27082176, 735243.27082176, 735244.27082176,
        735245.27082176, 735246.27082176, 735247.27082176, 735248.27082176
    ]

    y_data = [
        0.00000000e+00, 1.36094276e+02, 4.46608221e+03, 8.72660888e+03,
        1.31375786e+04, 1.73580193e+04, 2.29420671e+04, 3.12216341e+04,
        4.11395711e+04, 5.07972062e+04, 6.14904935e+04, 7.34275322e+04,
        7.87333933e+04, 8.46302456e+04, 9.71074959e+04, 1.07146672e+05
    ]

    # Create and fit the model
    regressor = RandomForestRegressor(n_estimators=10, max_depth=5, min_samples_split=2, random_state=42)
    regressor.fit(X_data, y_data)

    # Make predictions
    predictions = regressor.predict(X_data)

    print("Predictions:", predictions)

