        for w in words:
            if w == vocabulary[j]:
                count += 1

        if total_words > 0:
            tf_val = count / float(total_words)
        else:
            tf_val = 0.0

        tfidf_val = tf_val * idf_list[j]
        tfidf_vec.append(tfidf_val)

    return tfidf_vec

def find_most_similar_queries(documents, queries):
    vocabulary = get_vocabulary(documents)
    idf_list = calculate_idf(documents, vocabulary)

    doc_tfidf_matrix = calculate_tfidf_matrix(documents, vocabulary)

    normalized_doc_vectors = []
    for row in doc_tfidf_matrix:
        norm_row = normalize_vector(row)
        normalized_doc_vectors.append(norm_row)

    num_queries = len(queries)
    num_docs = len(documents)

    similarity_matrix = []

    for i in range(num_queries):
        query_vec = get_tfidf_for_query(queries[i], vocabulary, idf_list)
