import math

def tokenize(text):
    tokens = []
    current_word = ""
    for char in text:
        if char.isalnum():
            current_word += char.lower()
        else:
            if current_word:
                tokens.append(current_word)
                current_word = ""
    if current_word:
        tokens.append(current_word)
    return tokens

def get_document_frequencies(documents):
    doc_freqs = {}
    for doc in documents:
        tokens = tokenize(doc)
        unique_tokens = []
        seen = []
        for token in tokens:
            is_seen = False
            for s in seen:
                if s == token:
                    is_seen = True
                    break
            if not is_seen:
                seen.append(token)
                unique_tokens.append(token)

        for token in unique_tokens:
            if token in doc_freqs:
                doc_freqs[token] += 1
            else:
                doc_freqs[token] = 1
    return doc_freqs

def build_vocabulary(documents):
    vocab = []
    seen = []
    for doc in documents:
        tokens = tokenize(doc)
        for token in tokens:
            is_seen = False
            for s in seen:
                if s == token:
                    is_seen = True
                    break
            if not is_seen:
                seen.append(token)
                vocab.append(token)
    return vocab

def calculate_tf(tokens):
    tf = {}
    total_tokens = 0
    for token in tokens:
        total_tokens += 1
        if token in tf:
            tf[token] += 1
        else:
            tf[token] = 1

    for token in tf:
        tf[token] = tf[token] / total_tokens
    return tf

def calculate_idf(doc_freqs, num_docs):
    idf = {}
    for term, freq in doc_freqs.items():
        idf[term] = math.log(num_docs / (1 + freq))
    return idf

def get_tfidf_matrix(documents):
    vocab = build_vocabulary(documents)
    num_docs = len(documents)
    doc_freqs = get_document_frequencies(documents)
    idf = calculate_idf(doc_freqs, num_docs)

    matrix = []
    for doc in documents:
        tokens = tokenize(doc)
        tf = calculate_tf(tokens)
        row = []
        for term in vocab:
            if term in tf and term in idf:
                val = tf[term] * idf[term]
            else:
                val = 0.0
            row.append(val)
        matrix.append(row)

    return matrix, vocab

def get_tfidf_vector(query, vocab, doc_freqs, num_docs):
    tokens = tokenize(query)
    tf = calculate_tf(tokens)
    idf = calculate_idf(doc_freqs, num_docs)

    vector = []
    for term in vocab:
        if term in tf and term in idf:
            val = tf[term] * idf[term]
        else:
            val = 0.0
        vector.append(val)
    return vector

def calculate_vector_magnitude(vector):
    sum_sq = 0.0
    for val in vector:
        sum_sq += val * val
    return math.sqrt(sum_sq)

def calculate_dot_product(vec1, vec2):
    dot = 0.0
    i = 0
    while i < len(vec1):
        dot += vec1[i] * vec2[i]
        i += 1
    return dot

def get_cosine_similarity_matrix(documents, queries):
    tfidf_matrix, vocab = get_tfidf_matrix(documents)
    doc_freqs = get_document_frequencies(documents)
    num_docs = len(documents)

    query_vectors = []
    for query in queries:
        q_vec = get_tfidf_vector(query, vocab, doc_freqs, num_docs)
        query_vectors.append(q_vec)

    # Precompute magnitudes for documents
    doc_magnitudes = []
    for row in tfidf_matrix:
        mag = calculate_vector_magnitude(row)
        doc_magnitudes.append(mag)

    # Precompute magnitudes for queries
    query_magnitudes = []
    for q_vec in query_vectors:
        mag = calculate_vector_magnitude(q_vec)
        query_magnitudes.append(mag)

    similarity_matrix = []
    i = 0
    while i < len(queries):
        row_sim = []
        j = 0
        while j < len(documents):
            dot_prod = calculate_dot_product(query_vectors[i], tfidf_matrix[j])

            mag_q = query_magnitudes[i]
            mag_d = doc_magnitudes[j]

            if mag_q == 0 or mag_d == 0:
                sim = 0.0
            else:
                sim = dot_prod / (mag_q * mag_d)

            row_sim.append(sim)
            j += 1
        similarity_matrix.append(row_sim)
        i += 1

    return similarity_matrix

def find_most_similar_document_index(similarity_row):
    max_val = -2.0
    max_idx = 0
    idx = 0
    while idx < len(similarity_row):
        if similarity_row[idx] > max_val:
            max_val = similarity_row[idx]
            max_idx = idx
        idx += 1
    return max_idx

