import math

def get_term_frequency_inverse_data_frequency(documents):
    # Manual implementation of TF-IDF without sklearn
    # Returns a list of lists representing the TF-IDF matrix (rows=docs, cols=terms)

    # 1. Build vocabulary and count document frequencies
    vocab = {}
    doc_freq = {}

    for i, doc in enumerate(documents):
        words = doc.lower().split()
        unique_words_in_doc = set(words)

        for word in unique_words_in_doc:
            if word not in vocab:
                vocab[word] = 0
            vocab[word] += 1
            if word not in doc_freq:
                doc_freq[word] = 0
            doc_freq[word] += 1

    num_docs = len(documents)

    # 2. Calculate TF-IDF for each document
    tfidf_matrix = []

    for i, doc in enumerate(documents):
        words = doc.lower().split()
        word_counts = {}

        # Calculate Term Frequency (TF)
        for word in words:
            if word not in word_counts:
                word_counts[word] = 0
            word_counts[word] += 1

        tfidf_row = []

        # Iterate through all terms in vocabulary to maintain column order
        for term in vocab:
            df = doc_freq[term]

            if term in word_counts:
                tf = word_counts[term] / len(words)
                idf = math.log(num_docs / df) + 1.0 # Smoothing added
                tfidf_val = tf * idf
            else:
                tfidf_val = 0.0

            tfidf_row.append(tfidf_val)

        tfidf_matrix.append(tfidf_row)

    return tfidf_matrix

def get_tf_idf_query_similarity(documents, query):
    # 1. Prepare the query vector using the same vocabulary as documents
    tfidf_doc_matrix = get_term_frequency_inverse_data_frequency(documents)

    vocab = {}
    doc_freq = {}

    for i, doc in enumerate(documents):
        words = doc.lower().split()
        unique_words_in_doc = set(words)

        for word in unique_words_in_doc:
            if word not in vocab:
                vocab[word] = 0
            vocab[word] += 1
            if word not in doc_freq:
                doc_freq[word] = 0
            doc_freq[word] += 1

    num_docs = len(documents)

    # Process query to get TF-IDF values aligned with document vocabulary
    query_words = query.lower().split()
    query_word_counts = {}

    for word in query_words:
        if word not in query_word_counts:
            query_word_counts[word] = 0
        query_word_counts[word] += 1

    query_tfidf_row = []

    for term in vocab:
        df = doc_freq[term]

        if term in query_word_counts:
            tf = query_word_counts[term] / len(query_words)
            idf = math.log(num_docs / df) + 1.0
            tfidf_val = tf * idf
        else:
            tfidf_val = 0.0

        query_tfidf_row.append(tfidf_val)

    # Now we have the document matrix (list of lists) and the query vector (list)
    # We need to calculate cosine similarity for each document row against the query vector

    similarities = []

    for doc_row in tfidf_doc_matrix:
        # Calculate dot product
        dot_product = 0.0
        for i in range(len(doc_row)):
            dot_product += doc_row[i] * query_tfidf_row[i]

        # Calculate magnitude of document vector
        mag_doc = 0.0
        for val in doc_row:
            mag_doc += val * val

        if mag_doc > 0:
            mag_doc = math.sqrt(mag_doc)
        else:
            mag_doc = 1.0 # Avoid division by zero, though unlikely with TF-IDF

        # Calculate magnitude of query vector
        mag_query = 0.0
        for val in query_tfidf_row:
            mag_query += val * val

        if mag_query > 0:
            mag_query = math.sqrt(mag_query)
        else:
            mag_query = 1.0

        # Cosine similarity
        if mag_doc != 0 and mag_query != 0:
            sim = dot_product / (mag_doc * mag_query)
        else:
            sim = 0.0

        similarities.append(sim)

    return similarities

