import math

def tokenize(text):
    tokens = []
    current_word = ""
    for char in text:
        if char.isalnum():
            current_word += char.lower()
        else:
            if current_word:
                tokens.append(current_word)
                current_word = ""
    if current_word:
        tokens.append(current_word)
    return tokens

def get_vocabulary(documents):
    vocab = []
    for doc in documents:
        words = tokenize(doc)
        for word in words:
            is_new = True
            for existing in vocab:
                if existing == word:
                    is_new = False
                    break
            if is_new:
                vocab.append(word)
    return vocab

def get_document_frequencies(documents, vocabulary):
    df = []
    num_docs = len(documents)
    for i in range(num_docs):
        df.append(0)

    for doc in documents:
        words = tokenize(doc)
        unique_words_in_doc = []
        for w in words:
            is_unique = True
            for uw in unique_words_in_doc:
                if uw == w:
                    is_unique = False
                    break
            if is_unique:
                unique_words_in_doc.append(w)

        for word in unique_words_in_doc:
            for i in range(len(vocabulary)):
                if vocabulary[i] == word:
                    df[i] += 1
                    break
    return df

def calculate_tf(documents, vocabulary):
    tf_matrix = []
    num_docs = len(documents)
    num_vocab = len(vocabulary)

    for i in range(num_docs):
        row = []
        words = tokenize(documents[i])
        total_words = 0
        for w in words:
            total_words += 1

        for j in range(num_vocab):
            count = 0
            for w in words:
                if w == vocabulary[j]:
                    count += 1

            if total_words > 0:
                tf_val = count / float(total_words)
            else:
                tf_val = 0.0
            row.append(tf_val)
        tf_matrix.append(row)

    return tf_matrix

def calculate_idf(documents, vocabulary):
    num_docs = len(documents)
    df = get_document_frequencies(documents, vocabulary)
    idf_list = []

    for i in range(len(vocabulary)):
        if df[i] > 0:
            idf_val = math.log(float(num_docs) / float(df[i]))
        else:
            idf_val = 0.0
        idf_list.append(idf_val)

    return idf_list

def calculate_tfidf_matrix(documents, vocabulary):
    tf_matrix = calculate_tf(documents, vocabulary)
    idf_list = calculate_idf(documents, vocabulary)
    num_docs = len(documents)
    num_vocab = len(vocabulary)

    tfidf_matrix = []
    for i in range(num_docs):
        row = []
        for j in range(num_vocab):
            val = tf_matrix[i][j] * idf_list[j]
            row.append(val)
        tfidf_matrix.append(row)

    return tfidf_matrix

def calculate_vector_magnitude(vector):
    sum_sq = 0.0
    for val in vector:
        sum_sq += val * val
    return math.sqrt(sum_sq)

def calculate_dot_product(vec1, vec2):
    result = 0.0
    length = len(vec1)
    for i in range(length):
        result += vec1[i] * vec2[i]
    return result

def normalize_vector(vector):
    mag = calculate_vector_magnitude(vector)
    if mag == 0:
        return vector
    normalized = []
    for val in vector:
        normalized.append(val / mag)
    return normalized

def get_tfidf_for_query(query, vocabulary, idf_list):
    words = tokenize(query)
    total_words = 0
    for w in words:
        total_words += 1

    tfidf_vec = []
    num_vocab = len(vocabulary)

    for j in range(num_vocab):
        count = 0
        for w in words:
            if w == vocabulary[j]:
                count += 1

        if total_words > 0:
            tf_val = count / float(total_words)
        else:
            tf_val = 0.0

        tfidf_val = tf_val * idf_list[j]
        tfidf_vec.append(tfidf_val)

    return tfidf_vec

def find_most_similar_queries(documents, queries):
    vocabulary = get_vocabulary(documents)
    idf_list = calculate_idf(documents, vocabulary)

    doc_tfidf_matrix = calculate_tfidf_matrix(documents, vocabulary)

    normalized_doc_vectors = []
    for row in doc_tfidf_matrix:
        norm_row = normalize_vector(row)
        normalized_doc_vectors.append(norm_row)

    num_queries = len(queries)
    num_docs = len(documents)

    similarity_matrix = []

    for i in range(num_queries):
        query_vec = get_tfidf_for_query(queries[i], vocabulary, idf_list)
        norm_query_vec = normalize_vector(query_vec)

        row_similarities = []
        for j in range(num_docs):
            sim = calculate_dot_product(norm_query_vec, normalized_doc_vectors[j])
            row_similarities.append(sim)

        similarity_matrix.append(row_similarities)

    return similarity_matrix

