import math

def get_term_frequency_inverse_data_frequency(documents):
    # Manual implementation of TF-IDF without sklearn
    # Returns a list of lists representing the TF-IDF matrix (num_docs x num_terms)

    # 1. Build vocabulary and document frequency
    doc_freq = {}
    all_terms = set()

    for doc in documents:
        words = doc.lower().split()
        unique_words_in_doc = set(words)
        for word in unique_words_in_doc:
            all_terms.add(word)
            if word not in doc_freq:
                doc_freq[word] = 0
            doc_freq[word] += 1

    # Convert set to list for indexing
    term_list = sorted(list(all_terms))
    term_to_idx = {term: idx for idx, term in enumerate(term_list)}
    num_terms = len(term_list)

    # 2. Calculate TF-IDF for each document
    tfidf_matrix = []

    for doc in documents:
        words = doc.lower().split()
        if not words:
            tfidf_matrix.append([0.0] * num_terms)
            continue

        # Calculate Term Frequency (TF)
        term_counts = {}
        total_words = len(words)

        for word in words:
            if word in term_to_idx:
                if word not in term_counts:
                    term_counts[word] = 0
                term_counts[word] += 1

        # Calculate IDF
        num_docs = len(documents)
        idf_values = {}
        for term, df in doc_freq.items():
            if df == num_docs:
                idf_val = math.log(num_docs / (1 + df)) + 1
            else:
                idf_val = math.log((num_docs + 1) / (df + 1)) + 1
            idf_values[term] = idf_val

        # Build row
        row = []
        for term in term_list:
            tf = 0.0
            if term in term_counts:
                tf = term_counts[term] / total_words

            tfidf_val = tf * idf_values[term]
            row.append(tfidf_val)

        tfidf_matrix.append(row)

    return tfidf_matrix

def get_tf_idf_query_similarity(documents, query):
    # 1. Get document TF-IDF matrix
    doc_tfidf = get_term_frequency_inverse_data_frequency(documents)

    # 2. Calculate TF-IDF for the query manually
    words = query.lower().split()
    if not words:
        return []

    term_counts = {}
    total_words = len(words)

    for word in words:
        if word not in term_counts:
            term_counts[word] = 0
        term_counts[word] += 1

    # Calculate IDF using the same logic as in get_term_frequency_inverse_data_frequency
    num_docs = len(documents)
    doc_freq = {}

    for doc in documents:
        words_doc = doc.lower().split()
        unique_words_in_doc = set(words_doc)
        for word in unique_words_in_doc:
            if word not in doc_freq:
                doc_freq[word] = 0
            doc_freq[word] += 1

    idf_values = {}
    for term, df in doc_freq.items():
        if df == num_docs:
            idf_val = math.log(num_docs / (1 + df)) + 1
        else:
            idf_val = math.log((num_docs + 1) / (df + 1)) + 1
        idf_values[term] = idf_val

    # Build query TF-IDF vector
    query_tfidf = []
    for term in doc_freq.keys():
        tf = 0.0
        if term in term_counts:
            tf = term_counts[term] / total_words

        tfidf_val = tf * idf_values[term]
        query_tfidf.append(tfidf_val)

    # Ensure query vector has same length as document matrix columns
    # If query has terms not in documents, they are 0. 
    # If documents have terms not in query, they are 0 in query vector.
    # We need to align dimensions. The doc_tfidf is built based on all terms in documents.
    # The query_tfidf above only includes terms found in documents.
    # Let's rebuild query_tfidf to match the exact order of term_list from get_term_frequency_inverse_data_frequency logic

    # Re-run vocabulary building inside this function to ensure consistency if called standalone, 
    # but since we rely on doc_tfidf which already built it, we need to extract that info or re-build.
    # To keep it self-contained and consistent without global state, we re-calculate the exact same vocab structure.

    all_terms = set()
    for doc in documents:
        words_doc = doc.lower().split()
        for w in words_doc:
            all_terms.add(w)

    term_list = sorted(list(all_terms))
    num_terms = len(term_list)

    # Re-calculate IDF and TF-IDF for query aligned with term_list
    query_tfidf_aligned = []
    for term in term_list:
        tf = 0.0
        if term in term_counts:
            tf = term_counts[term] / total_words

        df = doc_freq.get(term, 0)
        num_docs = len(documents)

        if df == num_docs:
            idf_val = math.log(num_docs / (1 + df)) + 1
        else:
            idf_val = math.log((num_docs + 1) / (df + 1)) + 1

        tfidf_val = tf * idf_val
        query_tfidf_aligned.append(tfidf_val)

    # 3. Calculate Cosine Similarity for each document
    num_docs = len(documents)
    similarities = []

    for doc_row in doc_tfidf:
        # Dot product
        dot_product = 0.0
        for i in range(num_terms):
            dot_product += doc_row[i] * query_tfidf_aligned[i]

        # Magnitude of document vector
        mag_doc = 0.0
        for val in doc_row:
            mag_doc += val * val

        if mag_doc == 0:
            mag_doc = 1.0 # Avoid division by zero

        mag_doc = math.sqrt(mag_doc)

        # Magnitude of query vector
        mag_query = 0.0
        for val in query_tfidf_aligned:
            mag_query += val * val

        if mag_query == 0:
            mag_query = 1.0 # Avoid division by zero

        mag_query = math.sqrt(mag_query)

        # Cosine similarity
        if (mag_doc * mag_query) == 0:
            sim = 0.0
        else:
            sim = dot_product / (mag_doc * mag_query)

        similarities.append(sim)

    return similarities

def main():
    # Example usage with 3 queries and 5 documents
    documents = [
        "The quick brown fox jumps over the lazy dog",
        "A fast red cat runs under the slow turtle",
        "Python is a great programming language for data science",
        "Machine learning algorithms require large datasets",
        "Natural language processing helps computers understand text"
    ]

    queries = [
        "The quick brown fox jumps over the lazy dog",
        "A fast red cat runs under the slow turtle",
        "Python is a great programming language for data science"
    ]

    results = []
    for q in queries:
        sims = get_tf_idf_query_similarity(documents, q)
        results.append(sims)

    # Print the 3x5 matrix of similarities
    print("Similarity Matrix (3 queries x 5 documents):")
    for i, row in enumerate(results):
        print(f"Query {i+1}: {row}")

if __name__ == "__main__":
    main()

