def convert_variant_features_to_matrix(features):
    # Step 1: Find all unique features across all samples and sort them manually
    all_unique_features = []
    for sample in features:
        for feature in sample:
            if not is_in_list(all_unique_features, feature):
                all_unique_features.append(feature)

    # Sort the unique features list manually using bubble sort
    n_features = len(all_unique_features)
    for i in range(n_features):
        for j in range(0, n_features - i - 1):
            if compare_strings(all_unique_features[j], all_unique_features[j + 1]) > 0:
                temp = all_unique_features[j]
                all_unique_features[j] = all_unique_features[j + 1]
                all_unique_features[j + 1] = temp

    # Create a mapping from feature name to its index in the sorted list
    feature_to_index = {}
    for idx, feature_name in enumerate(all_unique_features):
        feature_to_index[feature_name] = idx

    # Step 2: Initialize the result matrix with zeros
    num_samples = len(features)
    num_cols = n_features
    result_matrix = []
    for i in range(num_samples):
        row = [0] * num_cols
        result_matrix.append(row)

    # Step 3: Populate the matrix based on the input features
    for sample_idx, sample in enumerate(features):
        for feature_name in sample:
            col_idx = feature_to_index[feature_name]
            result_matrix[sample_idx][col_idx] = 1

    return result_matrix

def is_in_list(lst, item):
    for element in lst:
        if element == item:
            return True
    return False

def compare_strings(s1, s2):
    # Manual string comparison without using built-in sort or min/max logic on strings directly
    len_s1 = 0
    len_s2 = 0
    while len_s1 < len(s1) and len_s2 < len(s2):
        char_s1 = ord(s1[len_s1])
        char_s2 = ord(s2[len_s2])
        if char_s1 != char_s2:
            return -1 if char_s1 < char_s2 else 1
        len_s1 += 1
        len_s2 += 1

    # If one is prefix of another, shorter comes first
    if len_s1 < len_s2:
        return -1
    elif len_s1 > len_s2:
        return 1
    else:
        return 0

