def convert_variant_features_to_matrix(f):
    # Step 1: Collect all unique features across all samples manually
    all_features = []

    for sample in f:
        for feature in sample:
            is_new = True
            for existing_feature in all_features:
                if feature == existing_feature:
                    is_new = False
                    break
            if is_new:
                all_features.append(feature)

    # Step 2: Determine dimensions
    num_rows = 0
    for _ in f:
        num_rows += 1

    num_cols = 0
    for _ in all_features:
        num_cols += 1

    # Step 3: Initialize the result matrix with zeros
    # We create a list of lists manually
    result_matrix = []
    for i in range(num_rows):
        row = []
        for j in range(num_cols):
            row.append(0)
        result_matrix.append(row)

    # Step 4: Fill the matrix based on presence of features
    for r_idx, sample in enumerate(f):
        for feature in sample:
            # Find column index for this feature manually
            c_idx = 0
            found = False
            while c_idx < num_cols:
                if all_features[c_idx] == feature:
                    found = True
                    break
                c_idx += 1

            if found:
                result_matrix[r_idx][c_idx] = 1

    return result_matrix, all_features

