import math

def read_data_from_file(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            parts = line.strip().split(',')
            row = []
            for part in parts:
                try:
                    val = float(part)
                    row.append(val)
                except ValueError:
                    continue
            if len(row) > 0:
                data.append(row)
    return data

def calculate_mean(values):
    total = 0.0
    count = 0
    for v in values:
        total += v
        count += 1
    if count == 0:
        return 0.0
    return total / count

def calculate_std_dev(values, mean_val):
    sum_sq_diff = 0.0
    count = 0
    for v in values:
        diff = v - mean_val
        sum_sq_diff += diff * diff
        count += 1
    if count == 0:
        return 0.0
    variance = sum_sq_diff / count
    return math.sqrt(variance)

def scale_and_center_data(data):
    if not data or len(data[0]) == 0:
        return []

    num_cols = len(data[0])
    scaled_data = []

    for col_idx in range(num_cols):
        column_values = []
        for row in data:
            if col_idx < len(row):
                column_values.append(row[col_idx])

        mean_val = calculate_mean(column_values)
        std_dev = calculate_std_dev(column_values, mean_val)

        if std_dev == 0.0:
            continue

        for row in data:
            if col_idx < len(row):
                original_val = row[col_idx]
                scaled_val = (original_val - mean_val) / std_dev
                row[col_idx] = scaled_val

    return data

def main():
    filename = "data.csv"
    try:
        raw_data = read_data_from_file(filename)
        if not raw_data:
            print("No valid data found.")
            return

        processed_data = scale_and_center_data(raw_data)

        with open("scaled_data.csv", 'w') as f:
            for row in processed_data:
                line = ",".join(str(x) for x in row)
                f.write(line + "\n")

        print("Data scaling and centering completed successfully.")
    except FileNotFoundError:
        print(f"File {filename} not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

