import random

def manual_read_csv(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            if line.strip() == '':
                continue
            row = []
            current_num = ''
            for char in line:
                if char == ',':
                    row.append(int(current_num))
                    current_num = ''
                else:
                    current_num += char
            if current_num != '':
                row.append(int(current_num))
            data.append(row)
    return data

def manual_split_data(data, train_ratio):
    random.shuffle(data)
    split_index = int(len(data) * train_ratio)
    training_set = data[:split_index]
    testing_set = data[split_index:]
    return training_set, testing_set

def separate_features_and_labels(dataset_list):
    x_list = []
    y_list = []
    for row in dataset_list:
        if len(row) == 0:
            continue
        feature_row = row[:-1]
        label = row[-1]
        x_list.append(feature_row)
        y_list.append(label)
    return x_list, y_list

def manual_sum(lst):
    total = 0
    for item in lst:
        total += item
    return total

def manual_max(lst):
    if len(lst) == 0:
        return None
    current_max = lst[0]
    for i in range(1, len(lst)):
        if lst[i] > current_max:
            current_max = lst[i]
    return current_max

def manual_min(lst):
    if len(lst) == 0:
        return None
    current_min = lst[0]
    for i in range(1, len(lst)):
        if lst[i] < current_min:
            current_min = lst[i]
    return current_min

def manual_sort_indices(indices, key_func):
    sorted_indices = list(indices)
    n = len(sorted_indices)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if key_func(sorted_indices[j]) < key_func(sorted_indices[min_idx]):
                min_idx = j
        sorted_indices[i], sorted_indices[min_idx] = sorted_indices[min_idx], sorted_indices[i]
    return sorted_indices

def manual_mean(lst):
    total = manual_sum(lst)
    count = len(lst)
    if count == 0:
        return None
    return total / count

