import csv
import math

def read_csv_data(filename):
    """Reads CSV file and returns a list of MSE values."""
    mse_values = []
    with open(filename, 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        for row in reader:
            if len(row) >= 2:
                try:
                    val = float(row[1])
                    mse_values.append(val)
                except ValueError:
                    continue
    return mse_values

def calculate_distance(point_a, point_b):
    """Calculates Euclidean distance between two points in 1D."""
    diff = point_a - point_b
    return math.sqrt(diff * diff)

def initialize_centroids(data, k):
    """Selects k random indices from data to initialize centroids."""
    import random
    n = len(data)
    if n < k:
        raise ValueError("Number of data points must be greater than or equal to k")

    indices = []
    while len(indices) < k:
        idx = random.randint(0, n - 1)
        if idx not in indices:
            indices.append(idx)

    centroids = []
    for idx in indices:
        centroids.append(data[idx])
    return centroids

def assign_clusters(data, centroids):
    """Assigns each data point to the nearest centroid."""
    labels = []
    for point in data:
        min_dist = float('inf')
        closest_cluster = 0

        for i, centroid in enumerate(centroids):
            dist = calculate_distance(point, centroid)
            if dist < min_dist:
                min_dist = dist
                closest_cluster = i

        labels.append(closest_cluster)
    return labels

def update_centroids(data, labels, k):
    """Calculates new centroids based on current cluster assignments."""
    n = len(data)
    new_centroids = []

    for i in range(k):
        sum_val = 0.0
        count = 0

        for j in range(n):
            if labels[j] == i:
                sum_val += data[j]
                count += 1

        if count > 0:
            new_centroids.append(sum_val / count)
        else:
            # If a cluster is empty, keep the old centroid or pick a random point
            # Here we just append 0 as a placeholder, though in practice we might re-initialize
            new_centroids.append(0.0)

    return new_centroids

def kmeans_1d(data, k=2, max_iterations=100):
    """Performs K-Means clustering on 1D data."""
    if len(data) == 0:
        return [], []

    centroids = initialize_centroids(data, k)
    labels = []

    for iteration in range(max_iterations):
        # Step 1: Assign clusters
        new_labels = assign_clusters(data, centroids)

        # Check for convergence
        if new_labels == labels:
            break

        labels = new_labels

        # Step 2: Update centroids
        old_centroids = centroids
        centroids = update_centroids(data, labels, k)

        # Check if centroids have stopped changing significantly
        changed = False
        for i in range(k):
            if abs(centroids[i] - old_centroids[i]) > 1e-6:
                changed = True
                break

        if not changed:
            break

    return labels, centroids

def main():
    filename = "generate_csv/all_data_device.csv"

    # Read data
    mse_values = read_csv_data(filename)

    if len(mse_values) == 0:
        print("No data found in the CSV file.")
        return

    # Perform K-Means with k=2
    labels, centroids = kmeans_1d(mse_values, k=2)

    # Calculate mean for each cluster manually to verify
    cluster_sums = [0.0, 0.0]
    cluster_counts = [0, 0]

    for i in range(len(mse_values)):
        label = labels[i]
        cluster_sums[label] += mse_values[i]
        cluster_counts[label] += 1

    calculated_means = []
    for i in range(2):
        if cluster_counts[i] > 0:
            calculated_means.append(cluster_sums[i] / cluster_counts[i])
        else:
            calculated_means.append(0.0)

    # Output results
    print("Cluster Assignments and Values:")
    for i in range(len(mse_values)):
        print(f"Index: {i}, MSE: {mse_values[i]}, Cluster: {labels[i]}")

    print("\nCentroids (Means):")
    for i in range(2):
        print(f"Cluster {i}: Mean = {centroids[i]:.4f}")

if __name__ == "__main__":
    main()

import csv
import math

def read_csv_to_list(filename):
    data = []
    with open(filename, 'r', newline='') as file:
        reader = csv.reader(file)
        header = next(reader)
        for row in reader:
            if len(row) >= 2:
                date_str = row[0].strip()
                try:
                    mse_val = float(row[1].strip())
                    data.append([date_str, mse_val])
                except ValueError:
                    continue
    return data

def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        return None
    year = int(parts[0])
    month = int(parts[1])
    day = int(parts[2])
    # Simple validation
    if month < 1 or month > 12:
        return None
    if day < 1 or day > 31:
        return None
    return (year, month, day)

def compare_dates(d1, d2):
    if d1 is None or d2 is None:
        return False
    for i in range(3):
        if d1[i] != d2[i]:
            return False
    return True

def sort_data_by_date(data):
    n = len(data)
    # Create indices list
    indices = []
    for i in range(n):
        indices.append(i)

    # Bubble sort indices based on date
    for i in range(n - 1):
        swapped = False
        for j in range(0, n - i - 1):
            idx1 = indices[j]
            idx2 = indices[j + 1]
            d1 = parse_date(data[idx1][0])
            d2 = parse_date(data[idx2][0])

            if compare_dates(d1, d2):
                # Equal dates, keep order (stable)
                continue

            is_less = False
            if d1[0] < d2[0]:
                is_less = True
            elif d1[0] == d2[0]:
                if d1[1] < d2[1]:
                    is_less = True
                elif d1[1] == d2[1]:
                    if d1[2] < d2[2]:
                        is_less = True

            if not is_less:
                # Swap
                indices[j], indices[j + 1] = indices[j + 1], indices[j]
                swapped = True

        if not swapped:
            break

    sorted_data = []
    for idx in indices:
        sorted_data.append(data[idx])

    return sorted_data

def calculate_mean(values):
    total = 0.0
    count = 0
    for v in values:
        total += v
        count += 1
    if count == 0:
        return 0.0
    return total / count

def euclidean_distance_sq(p1, p2):
    # p1 and p2 are lists of floats
    dist_sq = 0.0
    for i in range(len(p1)):
        diff = p1[i] - p2[i]
        dist_sq += diff * diff
    return dist_sq

def assign_clusters(data, centroids):
    n_points = len(data)
    n_clusters = len(centroids)
    labels = []

    for i in range(n_points):
        point = data[i][1] # mse value
        min_dist_sq = float('inf')
        best_cluster = 0

        for c in range(n_clusters):
            centroid = centroids[c]
            dist_sq = euclidean_distance_sq([point], [centroid])[0]
            if dist_sq < min_dist_sq:
                min_dist_sq = dist_sq
                best_cluster = c
        labels.append(best_cluster)

    return labels

def update_centroids(data, labels, n_clusters):
    centroids = []
    for c in range(n_clusters):
        cluster_points = []
        for i in range(len(data)):
            if labels[i] == c:
                cluster_points.append(data[i][1])

        if len(cluster_points) == 0:
            # If empty, keep old centroid or initialize to mean of all? 
            # For simplicity, we will skip update if empty, but standard KMeans needs a value.
            # We'll assume initial centroids are valid and won't be empty in first iteration.
            # If it happens later, we might need a fallback. Here we just return 0.0 for now to avoid crash.
            centroids.append(0.0)
        else:
            mean_val = calculate_mean(cluster_points)
            centroids.append(mean_val)

    return centroids

def kmeans_single_dimension(data, n_clusters, max_iterations=100):
    # Extract values
    values = []
    for item in data:
        values.append(item[1])

    # Initialize centroids randomly from data points
    import random
    random.seed(42) # For reproducibility
    indices = list(range(len(values)))
    random.shuffle(indices)
    initial_centroids = [values[indices[i]] for i in range(n_clusters)]

    centroids = initial_centroids

    for iteration in range(max_iterations):
        # Assign clusters
        labels = assign_clusters(data, centroids)

        # Update centroids
        new_centroids = update_centroids(data, labels, n_clusters)

        # Check convergence
        converged = True
        for i in range(n_clusters):
            if abs(new_centroids[i] - centroids[i]) > 1e-6:
                converged = False
                break

        if converged:
            break

        centroids = new_centroids

    return labels, centroids

def main():
    filename = "generate_csv/all_data_device.csv"

    # Read data
    raw_data = read_csv_to_list(filename)

    # Sort by date
    sorted_data = sort_data_by_date(raw_data)

    # Perform K-Means with k=2 on MSE values only
    n_clusters = 2
    labels, centroids = kmeans_single_dimension(sorted_data, n_clusters)

    # Calculate means for each cluster
    cluster_means = []
    for c in range(n_clusters):
        mean_val = calculate_mean(centroids[c]) # Centroids are already the means
        cluster_means.append(mean_val)

    # Print results
    print("Cluster Assignments (Date, MSE, Cluster Label):")
    for i in range(len(sorted_data)):
        print(f"{sorted_data[i][0]}, {sorted_data[i][1]:.2f}, {labels[i]}")

    print("\nCluster Centers (MSE Mean per cluster):")
    for c in range(n_clusters):
        print(f"Cluster {c}: {centroids[c]:.4f}")

if __name__ == "__main__":
    main()

class DecisionTreeClassifier:
    def __init__(self, max_depth=None):
        self.max_depth = max_depth
        self.tree = None
        self.unique_values_map = {}
        self.reverse_map = {}
        self.feature_names = []
        self.target_names = []
        self.target_to_int = {}
        self.int_to_target = {}

    def _encode_categorical(self, data):
        """Manually encodes string data to integers without using comprehensions or built-in aggregators."""
        unique_values = []

        # Extract unique values manually
        for item in data:
            is_new = True
            for existing in unique_values:
                if item == existing:
                    is_new = False
                    break
            if is_new:
                unique_values.append(item)

        # Create mapping
        mapping = {}
        idx = 0
        for val in unique_values:
            mapping[val] = idx
            idx += 1

        return mapping, unique_values

    def _encode_dataset(self, X, y):
        """Encodes both features and target."""
        # Encode features
        n_features = len(X[0]) if X else 0
        self.feature_names = list(range(n_features))

        for i in range(n_features):
            col_data = []
            for row in X:
                col_data.append(row[i])

            mapping, unique_vals = self._encode_categorical(col_data)
            self.unique_values_map[i] = mapping
            self.reverse_map[i] = {v: k for k, v in mapping.items()}

        # Encode target
        target_unique = []
        for val in y:
            is_new = True
            for existing in target_unique:
                if val == existing:
                    is_new = False
                    break
            if is_new:
                target_unique.append(val)

        self.target_names = target_unique
        self.target_to_int = {}
        self.int_to_target = {}
        idx = 0
        for val in target_unique:
            self.target_to_int[val] = idx
            self.int_to_target[idx] = val
            idx += 1

        # Convert X to integers
        X_encoded = []
        for row in X:
            new_row = []
            for i, val in enumerate(row):
                new_row.append(self.unique_values_map[i][val])
            X_encoded.append(new_row)

        # Convert y to integers
        y_encoded = []
        for val in y:
            y_encoded.append(self.target_to_int[val])

        return X_encoded, y_encoded

    def _calculate_entropy(self, labels):
        """Calculates entropy manually."""
        if len(labels) == 0:
            return 0.0

        # Count occurrences manually
        unique_labels = []
        counts = []

        for label in labels:
            found = False
            for i, existing in enumerate(unique_labels):
                if label == existing:
                    counts[i] += 1
                    found = True
                    break
            if not found:
                unique_labels.append(label)
                counts.append(1)

        total = len(labels)
        entropy = 0.0

        for count in counts:
            if count > 0:
                prob = float(count) / total
                if prob > 0:
                    import math
                    entropy -= prob * math.log2(prob)

        return entropy

    def _calculate_information_gain(self, parent_labels, left_labels, right_labels):
        """Calculates information gain."""
        if len(parent_labels) == 0:
            return 0.0

        parent_entropy = self._calculate_entropy(parent_labels)

        n_left = len(left_labels)
        n_right = len(right_labels)
        n_total = len(parent_labels)

        if n_total == 0:
            return 0.0

        left_entropy = self._calculate_entropy(left_labels)
        right_entropy = self._calculate_entropy(right_labels)

        weighted_entropy = (float(n_left) / n_total) * left_entropy + \
                          (float(n_right) / n_total) * right_entropy

        return parent_entropy - weighted_entropy

    def _find_best_split(self, X, y):
        """Finds the best feature and threshold to split on."""
        if len(X) == 0:
            return None, None, -1

        best_gain = -1
        best_feature = None
        best_threshold = None

        n_features = len(X[0])

        for feature_idx in range(n_features):
            # Get unique values for this feature
            unique_vals = []
            for row in X:
                val = row[feature_idx]
                is_new = True
                for existing in unique_vals:
                    if val == existing:
                        is_new = False
                        break
                if is_new:
                    unique_vals.append(val)

            # Try each unique value as a threshold (for categorical, we split on equality)
            for threshold in unique_vals:
                left_indices = []
                right_indices = []

                for i, row in enumerate(X):
                    if row[feature_idx] == threshold:
                        left_indices.append(i)
                    else:
                        right_indices.append(i)

                # Skip if split is empty
                if len(left_indices) == 0 or len(right_indices) == 0:
                    continue

                left_labels = [y[i] for i in left_indices]
                right_labels = [y[i] for i in right_indices]

                gain = self._calculate_information_gain(y, left_labels, right_labels)

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    def _build_tree(self, X, y, depth):
        """Recursively builds the decision tree."""
        # Check stopping conditions
        if self.max_depth is not None and depth >= self.max_depth:
            return self._create_leaf(y)

        # Check if all labels are the same
        unique_labels = []
        for label in y:
            found = False
            for existing in unique_labels:
                if label == existing:
                    found = True
                    break
            if not found:
                unique_labels.append(label)

        if len(unique_labels) <= 1:
            return self._create_leaf(y)

        # Find best split
        feature, threshold, gain = self._find_best_split(X, y)

        if feature is None or gain <= 0:
            return self._create_leaf(y)

        # Split data
        left_X = []
        left_y = []
        right_X = []
        right_y = []

        for i, row in enumerate(X):
            if row[feature] == threshold:
                left_X.append(row)
                left_y.append(y[i])
            else:
                right_X.append(row)
                right_y.append(y[i])

        # Build subtrees
        left_tree = self._build_tree(left_X, left_y, depth + 1)
        right_tree = self._build_tree(right_X, right_y, depth + 1)

        return {
            'feature': feature,
            'threshold': threshold,
            'left': left_tree,
            'right': right_tree
        }

    def _create_leaf(self, y):
        """Creates a leaf node with the most common label."""
        if len(y) == 0:
            return {'leaf': True, 'value': 0}

        # Count occurrences manually
        unique_labels = []
        counts = []

        for label in y:
            found = False
            for i, existing in enumerate(unique_labels):
                if label == existing:
                    counts[i] += 1
                    found = True
                    break
            if not found:
                unique_labels.append(label)
                counts.append(1)

        # Find max count manually
        max_count = -1
        max_label = unique_labels[0]

        for i, count in enumerate(counts):
            if count > max_count:
                max_count = count
                max_label = unique_labels[i]

        return {'leaf': True, 'value': max_label}

    def fit(self, X, y):
        """Fits the decision tree to the data."""
        # Encode string data to integers
        X_encoded, y_encoded = self._encode_dataset(X, y)

        # Build the tree
        self.tree = self._build_tree(X_encoded, y_encoded, 0)

        return self

    def _predict_single(self, x):
        """Predicts a single sample."""
        node = self.tree

        while not node['leaf']:
            feature = node['feature']
            threshold = node['threshold']

            if x[feature] == threshold:
                node = node['left']
            else:
                node = node['right']

        return node['value']

    def predict(self, X):
        """Predicts labels for multiple samples."""
        predictions = []

        # Encode input data
        X_encoded = []
        for row in X:
            new_row = []
            for i, val in enumerate(row):
                new_row.append(self.unique_values_map[i][val])
            X_encoded.append(new_row)

        # Predict each sample
        for x in X_encoded:
            pred_int = self._predict_single(x)
            pred_str = self.int_to_target[pred_int]
            predictions.append(pred_str)

        return predictions

    def _get_tree_info(self, node, depth=0):
        """Returns tree structure as string for debugging."""
        indent = "  " * depth

        if node['leaf']:
            return f"{indent}Leaf: {self.int_to_target[node['value']]}"

        feature_name = self.feature_names[node['feature']]
        threshold_val = self.reverse_map[node['feature']][node['threshold']]

        result = f"{indent}Split on Feature {feature_name} == '{threshold_val}'\n"
        result += f"{indent}Left:\n" + self._get_tree_info(node['left'], depth + 1) + "\n"
        result += f"{indent}Right:\n" + self._get_tree_info(node['right'], depth + 1)

        return result

    def get_tree_structure(self):
        """Returns the tree structure as a string."""
        if self.tree is None:
            return "Tree not trained yet."
        return self._get_tree_info(self.tree)


# Example usage with string data
if __name__ == "__main__":
    # Sample data with strings
    X = [['asdf', '1'], ['asdf', '0'], ['qwer', '1'], ['qwer', '0'], ['zxcv', '1']]
    y = ['2', '3', '2', '3', '2']

    # Create and train classifier
    clf = DecisionTreeClassifier(max_depth=3)
    clf.fit(X, y)

    # Make predictions
    test_X = [['asdf', '1'], ['qwer', '0']]
    predictions = clf.predict(test_X)

    print("Predictions:", predictions)
    print("\nTree Structure:")
    print(clf.get_tree_structure())

import sys

class SimpleEncoder:
    def __init__(self):
        self.columns = {}
        self.column_names = []

    def fit(self, data):
        num_cols = len(data[0])
        for col_idx in range(num_cols):
            unique_items = []
            for row in data:
                item = row[col_idx]
                if item not in unique_items:
                    unique_items.append(item)
            self.columns[col_idx] = {item: idx for idx, item in enumerate(unique_items)}
            self.column_names.append(col_idx)
        return self

    def transform(self, data):
        result = []
        for row in data:
            new_row = []
            for col_idx in range(len(row)):
                if row[col_idx] not in self.columns[col_idx]:
                    raise ValueError(f"Unknown value {row[col_idx]} in column {col_idx}")
                new_row.append(self.columns[col_idx][row[col_idx]])
            result.append(new_row)
        return result

class DecisionTreeClassifier:
    def __init__(self, max_depth=5):
        self.max_depth = max_depth
        self.tree = None

    def _gini(self, labels):
        if len(labels) == 0:
            return 0.0
        counts = {}
        for label in labels:
            if label not in counts:
                counts[label] = 0
            counts[label] += 1
        impurity = 0.0
        total = float(len(labels))
        for count in counts.values():
            prob = count / total
            impurity -= (prob * prob)
        return 1.0 - impurity

    def _best_split(self, X, y):
        best_gain = -1.0
        best_feature = None
        best_threshold = None

        num_features = len(X[0])
        current_impurity = self._gini(y)

        for feature_idx in range(num_features):
            values = []
            for row in X:
                values.append(row[feature_idx])

            unique_values = []
            for val in values:
                if val not in unique_values:
                    unique_values.append(val)

            for threshold_val in unique_values:
                left_indices = []
                right_indices = []

                for i, row in enumerate(X):
                    if row[feature_idx] <= threshold_val:
                        left_indices.append(i)
                    else:
                        right_indices.append(i)

                if len(left_indices) == 0 or len(right_indices) == 0:
                    continue

                left_y = [y[i] for i in left_indices]
                right_y = [y[i] for i in right_indices]

                left_impurity = self._gini(left_y)
                right_impurity = self._gini(right_y)

                total_samples = len(y)
                weighted_impurity = (len(left_y) * left_impurity + len(right_y) * right_impurity) / total_samples

                gain = current_impurity - weighted_impurity

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold_val

        return best_feature, best_threshold, best_gain

    def _build_tree(self, X, y, depth):
        num_samples = len(y)
        unique_labels = []
        for label in y:
            if label not in unique_labels:
                unique_labels.append(label)

        if len(unique_labels) == 1 or depth >= self.max_depth or num_samples <= 1:
            return {'leaf': True, 'class': unique_labels[0] if len(unique_labels) > 0 else None}

        feature, threshold, gain = self._best_split(X, y)

        if feature is None or gain <= 0:
            majority_label = None
            counts = {}
            for label in y:
                if label not in counts:
                    counts[label] = 0
                counts[label] += 1
            max_count = -1
            for label, count in counts.items():
                if count > max_count:
                    max_count = count
                    majority_label = label
            return {'leaf': True, 'class': majority_label}

        left_indices = []
        right_indices = []

        for i, row in enumerate(X):
            if row[feature] <= threshold:
                left_indices.append(i)
            else:
                right_indices.append(i)

        left_X = [X[i] for i in left_indices]
        left_y = [y[i] for i in left_indices]
        right_X = [X[i] for i in right_indices]
        right_y = [y[i] for i in right_indices]

        return {
            'leaf': False,
            'feature': feature,
            'threshold': threshold,
            'left': self._build_tree(left_X, left_y, depth + 1),
            'right': self._build_tree(right_X, right_y, depth + 1)
        }

    def fit(self, X, y):
        if len(X) == 0:
            raise ValueError("Input data cannot be empty")
        if len(y) != len(X):
            raise ValueError("Number of features must match number of labels")

        self.tree = self._build_tree(X, y, 0)
        return self

    def _predict_single(self, x, node):
        if node['leaf']:
            return node['class']

        if x[node['feature']] <= node['threshold']:
            return self._predict_single(x, node['left'])
        else:
            return self._predict_single(x, node['right'])

    def predict(self, X):
        predictions = []
        for row in X:
            pred = self._predict_single(row, self.tree)
            predictions.append(pred)
        return predictions

def main():
    raw_X = [['asdf', '1'], ['asdf', '0']]
    y = ['2', '3']

    encoder = SimpleEncoder()
    encoder.fit(raw_X)

    X_encoded = encoder.transform(raw_X)

    clf = DecisionTreeClassifier(max_depth=2)
    clf.fit(X_encoded, y)

    predictions = clf.predict(X_encoded)

    print("Predictions:", predictions)

if __name__ == "__main__":
    main()

class DecisionTreeClassifier:
    def __init__(self, max_depth=None):
        self.max_depth = max_depth
        self.tree = None
        self.unique_values_map = {}
        self.reverse_map = {}
        self.feature_names = []
        self.target_unique_values = []

    def _encode_data(self, X, y):
        # Encode features
        n_samples = len(X)
        if n_samples == 0:
            return [], []

        n_features = len(X[0])
        encoded_X = []

        for i in range(n_features):
            feature_values = []
            for row in X:
                feature_values.append(row[i])

            unique_vals = []
            for val in feature_values:
                is_new = True
                for u in unique_vals:
                    if u == val:
                        is_new = False
                        break
                if is_new:
                    unique_vals.append(val)

            mapping = {}
            rev_mapping = {}
            idx = 0
            for val in unique_vals:
                mapping[val] = float(idx)
                rev_mapping[float(idx)] = val
                idx += 1

            self.unique_values_map[i] = mapping
            self.reverse_map[i] = rev_mapping

        # Transform X
        for row in X:
            encoded_row = []
            for i in range(n_features):
                encoded_row.append(self.unique_values_map[i][row[i]])
            encoded_X.append(encoded_row)

        # Encode target
        unique_targets = []
        for val in y:
            is_new = True
            for u in unique_vals:
                if u == val:
                    is_new = False
                    break
            if is_new:
                unique_targets.append(val)

        target_mapping = {}
        idx = 0
        for val in unique_targets:
            target_mapping[val] = float(idx)
            idx += 1

        encoded_y = []
        for val in y:
            encoded_y.append(target_mapping[val])

        self.target_unique_values = unique_targets

        return encoded_X, encoded_y

    def _gini(self, labels):
        if len(labels) == 0:
            return 0.0

        counts = {}
        for label in labels:
            if label in counts:
                counts[label] += 1
            else:
                counts[label] = 1

        total = float(len(labels))
        impurity = 1.0
        for count in counts.values():
            prob = count / total
            impurity -= (prob * prob)

        return impurity

    def _information_gain(self, parent_labels, left_labels, right_labels):
        if len(parent_labels) == 0:
            return 0.0

        n = float(len(parent_labels))
        n_left = float(len(left_labels))
        n_right = float(len(right_labels))

        if n_left == 0 or n_right == 0:
            return 0.0

        parent_gini = self._gini(parent_labels)
        left_gini = self._gini(left_labels)
        right_gini = self._gini(right_labels)

        weighted_child_gini = (n_left / n) * left_gini + (n_right / n) * right_gini

        return parent_gini - weighted_child_gini

    def _find_best_split(self, X, y):
        best_gain = -1.0
        best_feature = -1
        best_threshold = None

        n_samples = len(X)
        if n_samples == 0:
            return None, None, None

        n_features = len(X[0])

        for feature_idx in range(n_features):
            # Get unique values for this feature to use as thresholds
            feature_values = []
            for row in X:
                feature_values.append(row[feature_idx])

            unique_vals = []
            for val in feature_values:
                is_new = True
                for u in unique_vals:
                    if u == val:
                        is_new = False
                        break
                if is_new:
                    unique_vals.append(val)

            # Sort unique values manually (bubble sort)
            len_unique = len(unique_vals)
            for i in range(len_unique):
                for j in range(i + 1, len_unique):
                    if unique_vals[i] > unique_vals[j]:
                        temp = unique_vals[i]
                        unique_vals[i] = unique_vals[j]
                        unique_vals[j] = temp

            # Try thresholds between unique values
            for i in range(len_unique - 1):
                threshold = (unique_vals[i] + unique_vals[i+1]) / 2.0

                left_labels = []
                right_labels = []

                for k in range(n_samples):
                    if X[k][feature_idx] <= threshold:
                        left_labels.append(y[k])
                    else:
                        right_labels.append(y[k])

                gain = self._information_gain(y, left_labels, right_labels)

                if gain > best_gain:
                    best_gain = gain
                    best_feature = feature_idx
                    best_threshold = threshold

        return best_feature, best_threshold, best_gain

    def _build_tree(self, X, y, depth):
        # Check stopping conditions
        if self.max_depth is not None and depth >= self.max_depth:
            return self._create_leaf(y)

        # Check if all labels are the same
        first_label = y[0]
        all_same = True
        for label in y:
            if label != first_label:
                all_same = False
                break

        if all_same or len(y) == 0:
            return self._create_leaf(y)

        # Find best split
        feature_idx, threshold, gain = self._find_best_split(X, y)

        if feature_idx is None or gain <= 0.0:
            return self._create_leaf(y)

        # Split data
        left_X = []
        right_X = []
        left_y = []
        right_y = []

        for i in range(len(X)):
            if X[i][feature_idx] <= threshold:
                left_X.append(X[i])
                left_y.append(y[i])
            else:
                right_X.append(X[i])
                right_y.append(y[i])

        # Recursively build subtrees
        left_subtree = self._build_tree(left_X, left_y, depth + 1)
        right_subtree = self._build_tree(right_X, right_y, depth + 1)

        return {
            'feature': feature_idx,
            'threshold': threshold,
            'left': left_subtree,
            'right': right_subtree
        }

    def _create_leaf(self, y):
        if len(y) == 0:
            return {'leaf': True, 'value': None}

        # Count votes
        counts = {}
        for label in y:
            if label in counts:
                counts[label] += 1
            else:
                counts[label] = 1

        # Find majority class manually
        max_count = -1
        majority_label = None
        for label, count in counts.items():
            if count > max_count:
                max_count = count
                majority_label = label

        return {'leaf': True, 'value': majority_label}

    def fit(self, X, y):
        # Store original feature names if needed (not strictly necessary for logic)
        self.feature_names = list(range(len(X[0]))) if len(X) > 0 else []

        # Encode data
        encoded_X, encoded_y = self._encode_data(X, y)

        # Build tree
        self.tree = self._build_tree(encoded_X, encoded_y, 0)

        return self

    def _predict_single(self, x):
        # Encode single sample
        encoded_x = []
        for i in range(len(x)):
            if i in self.unique_values_map:
                encoded_x.append(self.unique_values_map[i][x[i]])
            else:
                encoded_x.append(0.0)

        node = self.tree

        while not node['leaf']:
            feature_idx = node['feature']
            threshold = node['threshold']

            if encoded_x[feature_idx] <= threshold:
                node = node['left']
            else:
                node = node['right']

        return node['value']

    def predict(self, X):
        predictions = []
        for row in X:
            pred_encoded = self._predict_single(row)

            # Map back to original string value
            if pred_encoded is not None and len(self.target_unique_values) > 0:
                # Find the index of pred_encoded in target_unique_values
                idx = 0
                found = False
                for val in self.target_unique_values:
                    if float(idx) == pred_encoded:
                        predictions.append(val)
                        found = True
                        break
                    idx += 1

                if not found:
                    # Fallback if mapping fails
                    predictions.append(self.target_unique_values[0])
            else:
                predictions.append(None)

        return predictions

    def score(self, X, y):
        predictions = self.predict(X)
        correct = 0
        for i in range(len(y)):
            if predictions[i] == y[i]:
                correct += 1

        if len(y) == 0:
            return 0.0

        return float(correct) / float(len(y))


# Example usage with string data
if __name__ == "__main__":
    # Sample data
    X = [['dsa', '2'], ['sato', '3'], ['dsa', '3'], ['sato', '2']]
    y = ['4', '5', '5', '4']

    clf = DecisionTreeClassifier()
    clf.fit(X, y)

    # Predict on training data
    predictions = clf.predict(X)

    print("Predictions:", predictions)
    print("Actual:", y)
    print("Score:", clf.score(X, y))

